        function getBLOSUM62Score(a, b) {
            a = a.toUpperCase();
            b = b.toUpperCase();

            // Unknown/non-standard residues are treated as X.
            const ia = BLOSUM62_INDEX[a] ?? BLOSUM62_INDEX["X"];
            const ib = BLOSUM62_INDEX[b] ?? BLOSUM62_INDEX["X"];

            return BLOSUM62_VALUES[
                ia * BLOSUM62_ALPHABET.length + ib
            ];
        }

        function isSimilarAA(a, b) {
            // Gaps are never amino-acid similarities.
            if (a === '-' || b === '-') return false;

            return getBLOSUM62Score(a, b) > 0;
        }

        // Color Tables pre-converted to 32-bit packed integers for ultra-fast ImageData rendering
        const VIRIDIS_HEX = ['#440154', '#482878', '#3e4989', '#31688e', '#26828e', '#1f9e89', '#35b779', '#6ece58', '#b5de2b', '#fde725'];
        const SPECTRAL_HEX = ['#9e0142', '#d53e4f', '#f46d43', '#fdae61', '#fee08b', '#e6f598', '#abdda4', '#66c2a5', '#3288bd', '#5e4fa2'];
        const COOLWARM_HEX = ['#3b4cc0', '#6788ee', '#9abbff', '#c9d7f0', '#edd1c2', '#f7a58b', '#e26952', '#b40426'];

        function hexToRgb(hex) {
            const bigint = parseInt(hex.replace('#', ''), 16);
            return [(bigint >> 16) & 255, (bigint >> 8) & 255, bigint & 255];
        }

        function interpolateColor(c1, c2, factor) {
            return [
                Math.round(c1[0] + factor * (c2[0] - c1[0])),
                Math.round(c1[1] + factor * (c2[1] - c1[1])),
                Math.round(c1[2] + factor * (c2[2] - c1[2]))
            ];
        }

        function getGradientColorRgb(colors, value) {
            const v = Math.max(0, Math.min(1, value));
            if (v === 0) return colors[0];
            if (v === 1) return colors[colors.length - 1];
            const step = 1 / (colors.length - 1);
            const idx = Math.floor(v / step);
            const factor = (v - idx * step) / step;
            return interpolateColor(colors[idx], colors[Math.min(idx + 1, colors.length - 1)], factor);
        }

