        let referenceSpeciesTimer = null, referenceSpeciesController = null, referenceSpeciesRevision = 0;
        const referenceSpeciesCache = new Map();
        function matchStringSpecies(organism) {
            const exact = stringSpeciesCatalog[String(organism.ncbi_taxonomy_id)];
            if (exact) return {taxon:String(organism.ncbi_taxonomy_id), name:exact[0]};
            const name = organism.ncbi_scientific_name?.toLowerCase();
            const matches = Object.entries(stringSpeciesCatalog).filter(([,names]) => names.some(n => n.toLowerCase() === name));
            if (matches.length === 1) return {taxon:matches[0][0], name:matches[0][1][0]};
            const binomial = value => {
                const words = String(value || '').trim().split(/\s+/);
                return words.length >= 2 && !['sp.', 'spp.', 'bacterium'].includes(words[1].toLowerCase())
                    ? words.slice(0,2).join(' ').toLowerCase() : null;
            };
            const species = binomial(organism.ncbi_scientific_name);
            if (!species) return null;
            const candidates = Object.entries(stringSpeciesCatalog).filter(([,names]) => names.some(n => binomial(n) === species));
            // Prefer a species-level record, then choose a stable taxon ID among strains.
            candidates.sort((a,b) => Number(b[1].some(n => n.toLowerCase() === species)) - Number(a[1].some(n => n.toLowerCase() === species)) || Number(a[0])-Number(b[0]));
            return candidates.length ? {taxon:candidates[0][0], name:candidates[0][1][0], speciesFallback:true} : null;
        }
        function scheduleReferenceSpeciesLookup(raw, delay = 400) {
            clearTimeout(referenceSpeciesTimer);
            referenceSpeciesController?.abort();
            const revision = ++referenceSpeciesRevision;
            const note = document.getElementById('referenceSpeciesNote'), links = document.getElementById('referenceSpeciesLinks'), status = document.getElementById('referenceSpeciesStatus');
            note.textContent = ''; links.replaceChildren(); status.textContent = '';
            let ids=[]; try { ids=referenceInputParts(raw).ids.filter(id=>/^[0-9][A-Z0-9]{3}$/.test(id)); } catch (_) {}
            if (!ids.length) return;
            referenceSpeciesTimer = setTimeout(async () => {
                const controller = new AbortController(); referenceSpeciesController = controller;
                status.textContent = 'Looking up reference source species…';
                try {
                    const results=await Promise.all(ids.map(async id=>{
                    let organisms = referenceSpeciesCache.get(id);
                    if (!organisms) {
                        const query = `{entry(entry_id:"${id}"){polymer_entities{entity_poly{rcsb_entity_polymer_type}rcsb_entity_source_organism{ncbi_taxonomy_id ncbi_scientific_name}}}}`;
                        const response = await fetch('https://data.rcsb.org/graphql?query=' + encodeURIComponent(query), {signal:controller.signal});
                        if (!response.ok) throw new Error('Species lookup failed');
                        const data = await response.json();
                        if (data.errors || !data.data?.entry) throw new Error('Species metadata unavailable');
                        const unique = new Map();
                        for (const entity of data.data.entry.polymer_entities || []) {
                            if (entity.entity_poly?.rcsb_entity_polymer_type !== 'Protein') continue;
                            for (const organism of entity.rcsb_entity_source_organism || []) {
                                if (organism.ncbi_scientific_name) unique.set(String(organism.ncbi_taxonomy_id || organism.ncbi_scientific_name), organism);
                            }
                        }
                        organisms = [...unique.values()]; referenceSpeciesCache.set(id, organisms);
                    }
                    return {id,organisms};
                    }));
                    if (revision !== referenceSpeciesRevision) return;
                    const names=[...new Set(results.flatMap(result=>result.organisms.map(organism=>organism.ncbi_scientific_name)))];
                    if (!names.length) {status.textContent = 'No source species is recorded for these references.'; return;}
                    note.replaceChildren(document.createTextNode(' (note that '));
                    results.forEach((result,index)=>{
                        if(index)note.appendChild(document.createTextNode('; '));
                        const pdbLabel = document.createElement('span'); pdbLabel.className = 'text-teal-400'; pdbLabel.textContent = result.id;
                        note.appendChild(pdbLabel,document.createTextNode(' is from '));
                        result.organisms.forEach((organism,j)=>{
                            if(j)note.appendChild(document.createTextNode(', '));
                            const speciesLabel = document.createElement('em'); speciesLabel.textContent = organism.ncbi_scientific_name;
                            note.appendChild(speciesLabel);
                        });
                    });
                    note.appendChild(document.createTextNode(')'));
                    const shown = new Set();
                    let unmatched = false;
                    for (const organism of results.flatMap(result=>result.organisms)) {
                        const species = matchStringSpecies(organism);
                        if (!species) {unmatched = true; continue;}
                        if (shown.has(species.taxon)) continue;
                        shown.add(species.taxon);
                        const link = document.createElement('a');
                        link.href = 'https://string-db.org/cgi/download?species_text=' + encodeURIComponent(species.name);
                        link.target = '_blank'; link.rel = 'noopener noreferrer';
                        link.className = 'inline-flex items-center gap-2 rounded-xl border border-teal-500/40 bg-teal-700 hover:bg-teal-600 px-3 py-2 text-xs text-white';
                        link.textContent = `${species.name} STRING download page`;
                        link.title = `STRING taxon ${species.taxon}${species.speciesFallback ? ' — same genus and species; strain may differ' : ''} — opens in a new tab`;
                        const icon = document.createElement('i'); icon.className = 'fa-solid fa-arrow-up-right-from-square'; icon.setAttribute('aria-hidden','true');
                        link.appendChild(icon); links.appendChild(link);
                    }
                    status.textContent = unmatched ? 'Some source species have no genus-and-species match in the STRING 12.5 catalog. You can search STRING manually above.' : '';
                } catch (error) {
                    if (revision === referenceSpeciesRevision && error.name !== 'AbortError') status.textContent = 'Could not look up the source species for the reference PDBs. You can still search STRING manually.';
                }
            }, delay);
        }

// referenceSpeciesLookup.js end

// molstarInput.js start
        async function updateReferenceStructureName(entry, generation) {
            const label = document.getElementById('referenceStructureName');
            label.textContent = entry.sequence ? 'Reference: sequence' : 'Reference: ' + entry.id;
            if (entry.sequence || !/^[0-9][A-Z0-9]{3}$/i.test(entry.id)) return;
            try {
                const response = await fetch(`https://data.rcsb.org/rest/v1/core/entry/${encodeURIComponent(entry.id)}`);
                if (!response.ok) return;
                const data = await response.json();
                if (generation === modelBuildGeneration && data.struct?.title) label.textContent = `Reference: ${data.struct.title}`;
            } catch (error) { /* Structure loading can proceed if metadata is unavailable. */ }
        }

        function molstarCoordinateData(file) {
            if (file.format !== 'mmcif') return file.text;
            // Mol* selects a CIF data block; exclude metadata-only blocks before coordinates.
            const blocks = file.text.replace(/^\uFEFF/, '').split(/(?=^data_\S+)/m);
            const coordinates = blocks.find(block => /^data_/m.test(block) && /^_atom_site\.Cartn_x\b/m.test(block));
            if (!coordinates) throw new Error(`No mmCIF coordinate block found in ${file.pdbId}.`);
            return coordinates;
        }
        async function loadFetchedStructureIntoMolstar(viewer, file, reference = false) {
            try {
                // Use Mol*'s public convenience loader. It creates the data cell,
                // trajectory, model, structure, and default representation in the
                // order required by the bundled Mol* build.
                await viewer.loadStructureFromData(molstarCoordinateData(file), file.format, { dataLabel: file.pdbId });
            } catch (error) {
                if (!reference || !/^[0-9][A-Z0-9]{3}$/i.test(file.pdbId)) throw error;
                const response = await fetch(`https://files.rcsb.org/download/${file.pdbId.toUpperCase()}.cif`);
                if (!response.ok) throw new Error(`Reference viewer failed: ${error.message}. mmCIF fallback returned HTTP ${response.status}.`);
                const fallback = {pdbId:file.pdbId,format:'mmcif',text:await response.text()};
                await viewer.plugin.clear();
                await viewer.loadStructureFromData(molstarCoordinateData(fallback), 'mmcif', { dataLabel: file.pdbId });
            }
        }
        let alphaFoldMolstarFiles = [];
        async function setAlphaFoldMolstarColor(mode) {
            if (!molstarViewer2?.plugin) return;
            const plugin = molstarViewer2.plugin;
            try {
                const structures = plugin.managers.structure.hierarchy.selection.structures;
                for (let i=0;i<structures.length;i++) {
                    const file = alphaFoldMolstarFiles[i];
                    const params = mode !== 'plddt' ? {color:'chain-id'} : !file?.alphaFoldCoordinates ? {color:'uniform',colorParams:{value:0x94a3b8}} :
                        file.format==='mmcif' && /_ma_qa_metric_local\./.test(file.text) ? {color:'plddt-confidence'} :
                        {color:'uncertainty',colorParams:{domain:[0,100],list:{kind:'interpolate',colors:[[0xff7d45,0],[0xffdb13,.5],[0x65cbf3,.7],[0x0053d6,.9],[0x0053d6,1]]}}};
                    await plugin.managers.structure.component.updateRepresentationsTheme(structures[i].components, params);
                }
            } catch (error) { console.warn('AlphaFold colour theme could not be applied:', error); }
        }

// molstarInput.js end

// stringSpeciesMatching.js start
        // STRING files stay local. Parse and score in a worker to keep the UI responsive.
        function stringMatchingWorker() {
            async function* lines(file) {
                const reader = file.stream().getReader(), decoder = new TextDecoder();
                let pending = '';
                try {
                    while (true) {
                        const {value, done} = await reader.read();
                        pending += done ? decoder.decode() : decoder.decode(value, {stream:true});
                        let start = 0, end;
                        while ((end = pending.indexOf('\n', start)) !== -1) {
                            yield pending.slice(start,end).replace(/\r$/, ''); start = end + 1;
                        }
                        pending = pending.slice(start);
                        if (done) { if (pending) yield pending.replace(/\r$/, ''); break; }
                    }
                } finally { reader.releaseLock(); }
            }
            function kmers(sequence, k) {
                const result = new Set();
                for (let i=0;i<=sequence.length-k;i++) result.add(sequence.slice(i,i+k));
                return result;
            }
            // Score-only affine-gap Smith–Waterman, with O(target length) memory.
            function smithWaterman(query, target, matrix, alphabet, open, extend) {
                const index = Object.fromEntries(Array.from(alphabet, (aa,i)=>[aa,i]));
                const encode = seq => Int32Array.from(seq, aa=>index[aa] ?? index.X);
                const q=encode(query), t=encode(target), width=t.length+1, stride=alphabet.length;
                let M=new Int32Array(width), X=new Int32Array(width), Y=new Int32Array(width);
                let nextM=new Int32Array(width), nextX=new Int32Array(width), nextY=new Int32Array(width), best=0;
                for (let i=0;i<q.length;i++) {
                    nextM[0]=nextX[0]=nextY[0]=0;
                    for (let j=1;j<width;j++) {
                        nextM[j]=Math.max(0,Math.max(M[j-1],X[j-1],Y[j-1])+matrix[q[i]*stride+t[j-1]]);
                        nextX[j]=Math.max(0,M[j]+open,X[j]+extend,Y[j]+open);
                        nextY[j]=Math.max(0,nextM[j-1]+open,nextY[j-1]+extend,nextX[j-1]+open);
                        best=Math.max(best,nextM[j],nextX[j],nextY[j]);
                    }
                    [M,nextM]=[nextM,M]; [X,nextX]=[nextX,X]; [Y,nextY]=[nextY,Y];
                }
                return best;
            }
            self.onmessage = async ({data}) => {
                try {
                    const {sequencesFile, aliasesFile, queries, taxon, matrix, alphabet, gapOpen, gapExtend}=data;
                    // Repeated reference sequences share one shortlist and alignment run.
                    const groups = new Map();
                    for (const query of queries) {
                        if (!groups.has(query.sequence)) groups.set(query.sequence,{sequence:query.sequence,chains:[],k:Math.min(3,query.sequence.length),shortlist:[]});
                        groups.get(query.sequence).chains.push(query.chain);
                    }
                    for (const group of groups.values()) group.words=kmers(group.sequence,group.k);
                    let id=null, fragments=[], count=0;
                    function accept() {
                        if (!id) return;
                        const sequence=fragments.join('').toUpperCase().replace(/\*$/, '');
                        if (!sequence || !/^[ACDEFGHIKLMNPQRSTVWYBXZJUO]+$/.test(sequence)) throw new Error(`Invalid protein sequence for ${id}.`);
                        const sets=new Map(); count++;
                        for (const group of groups.values()) {
                            if (!sets.has(group.k)) sets.set(group.k,kmers(sequence,group.k));
                            let hits=0;
                            for (const word of group.words) if (sets.get(group.k).has(word)) hits++;
                            group.shortlist.push({id,sequence,hits});
                            // Keep memory bounded while scanning large species proteomes.
                            if (group.shortlist.length>=1000) trim(group);
                        }
                    }
                    function trim(group) {
                        group.shortlist.sort((a,b)=>b.hits-a.hits || a.id.localeCompare(b.id));
                        group.shortlist.length=Math.min(500,group.shortlist.length);
                    }
                    self.postMessage({progress:'Reading species FASTA and filtering by shared 3-mers…'});
                    for await (const raw of lines(sequencesFile)) {
                        const line=raw.trim(); if(!line) continue;
                        // Also accept the first STRING identifier without a leading >.
                        if(line.startsWith('>') || /^\d+\.\S+$/.test(line)) {
                            accept(); id=line.replace(/^>/,'').split(/\s+/)[0]; fragments=[];
                            if(!id.startsWith(taxon+'.')) throw new Error(`FASTA identifier ${id} does not match taxon ${taxon}.`);
                        } else {
                            if(!id) throw new Error('FASTA sequence found before a STRING protein identifier.');
                            fragments.push(line.replace(/\s/g,''));
                        }
                    }
                    accept(); if(!count) throw new Error('The FASTA file contains no proteins.');
                    const matches=[]; let groupNumber=0;
                    for(const group of groups.values()) {
                        trim(group); let best=null, ties=0;
                        for(let i=0;i<group.shortlist.length;i++) {
                            const candidate=group.shortlist[i];
                            if(i%10===0) self.postMessage({progress:`Smith–Waterman: reference ${groupNumber+1}/${groups.size}, candidate ${i+1}/${group.shortlist.length}…`});
                            const score=smithWaterman(group.sequence,candidate.sequence,matrix,alphabet,gapOpen,gapExtend);
                            if(!best || score>best.score) {best={...candidate,score};ties=1;}
                            else if(score===best.score) {ties++;if(candidate.id.localeCompare(best.id)<0)best={...candidate,score};}
                        }
                        for(const chain of group.chains) matches.push({chain,protein:best.score>0?best.id:null,score:best.score,ties,shortlist:group.shortlist.length});
                        groupNumber++;
                    }
                    self.postMessage({progress:'Resolving UniProt accessions from aliases…'});
                    const wanted=new Map(matches.filter(m=>m.protein).map(m=>[m.protein,{preferred:new Set(),fallback:new Set()}]));
                    let validRows=0;
                    const accession=/^(?:[OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9](?:[A-Z][A-Z0-9]{2}[0-9]){1,2})(?:-[0-9]+)?$/;
                    for await(const raw of lines(aliasesFile)) {
                        if(!raw.trim() || raw.startsWith('#'))continue;
                        const [protein,alias,source]=raw.split('\t');
                        if(protein==='string_protein_id')continue;
                        if(!protein || !alias || !source)throw new Error('Aliases must have tab-separated string_protein_id, alias and source columns.');
                        if(!protein.startsWith(taxon+'.'))throw new Error(`Alias identifier ${protein} does not match taxon ${taxon}.`);
                        validRows++;
                        const record=wanted.get(protein), value=alias.trim().toUpperCase();
                        if(!record || !accession.test(value))continue;
                        const sources=source.trim().split(/[\s;,]+/);
                        if(sources.includes('RefSeq_xref_UniProtKB_Swiss_Prot'))record.preferred.add(value);
                        else if(sources.includes('UniProt_AC'))record.fallback.add(value);
                    }
                    if(!validRows)throw new Error('The aliases file contains no alias records.');
                    for(const match of matches) {
                        const record=wanted.get(match.protein);
                        const ids=record ? Array.from(record.preferred.size?record.preferred:record.fallback).sort() : [];
                        match.accession=ids[0] || null;
                        match.aliasCount=ids.length;
                        match.source=record?.preferred.size?'RefSeq_xref_UniProtKB_Swiss_Prot':'UniProt_AC';
                    }
                    self.postMessage({matches,count});
                } catch(error) { self.postMessage({error:error.message}); }
            };
        }

        function preferredNamesWorker() {
            self.onmessage = async ({data:file}) => {
                try {
                    const names=new Map(), links=new Map();
                    const priorities=['UniProt_GN_Name','RefSeq_gene','KEGG_NAME'];
                    const accession=/^(?:[OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9](?:[A-Z][A-Z0-9]{2}[0-9]){1,2})(?:-[0-9]+)?$/;
                    let rows=0;
                    function consume(line) {
                        if(!line.trim() || line.startsWith('#'))return;
                        const [protein,rawAlias,rawSource]=line.replace(/\r$/,'').split('\t');
                        if(protein==='string_protein_id')return;
                        if(!protein||!rawAlias||!rawSource)throw new Error('Aliases must contain three tab-separated columns.');
                        rows++;
                        const alias=rawAlias.trim(),sources=rawSource.trim().split(/[\s;,]+/);
                        const rank=priorities.findIndex(source=>sources.includes(source));
                        if(rank!==-1) {
                            let record=names.get(protein);
                            if(!record || rank<record.rank){record={rank,names:new Set()};names.set(protein,record);}
                            if(rank===record.rank)record.names.add(alias);
                        }
                        if(accession.test(alias.toUpperCase())) {
                            const key=alias.toUpperCase();
                            if(!links.has(key))links.set(key,new Set());
                            links.get(key).add(protein);
                        }
                    }
                    const reader=file.stream().getReader(),decoder=new TextDecoder();let pending='';
                    try {
                        while(true) {
                            const {value,done}=await reader.read();
                            pending+=done?decoder.decode():decoder.decode(value,{stream:true});
                            let start=0,end;
                            while((end=pending.indexOf('\n',start))!==-1){consume(pending.slice(start,end));start=end+1;}
                            pending=pending.slice(start);
                            if(done){if(pending)consume(pending);break;}
                        }
                    } finally {reader.releaseLock();}
                    if(!rows)throw new Error('The aliases file contains no alias records.');
                    const result=[];
                    for(const [protein,record] of names)result.push([protein,{name:Array.from(record.names).sort().join(' / '),source:priorities[record.rank]}]);
                    for(const [id,proteins] of links) {
                        const labels=new Set(),sources=new Set();
                        for(const protein of proteins){const record=names.get(protein);if(record){record.names.forEach(name=>labels.add(name));sources.add(priorities[record.rank]);}}
                        if(labels.size)result.push([id,{name:Array.from(labels).sort().join(' / '),source:Array.from(sources).join(', ')}]);
                    }
                    self.postMessage({entries:result});
                } catch(error){self.postMessage({error:error.message});}
            };
        }
        let preferredNames = new Map(), preferredNamesJob = null, preferredNamesState = '';
        let stringAliasStatusReference = null, stringMatchStatusReference = null;
        const selectedStringFiles={sequence:null,aliases:null};
        const stringSequenceFile=()=>selectedStringFiles.sequence;
        const stringAliasesFile=()=>selectedStringFiles.aliases;
        function selectStringFiles(input){
            let invalid=false,aliasesChanged=false;
            for(const file of input.files){
                if(/^\d+\.protein\.sequences\.v[\d.]+\.fa$/i.test(file.name))selectedStringFiles.sequence=file;
                else if(/^\d+\.protein\.aliases\.v[\d.]+\.txt$/i.test(file.name)){
                    aliasesChanged=selectedStringFiles.aliases!==file;selectedStringFiles.aliases=file;
                }else invalid=true;
            }
            const picker=input.closest('.string-file-picker'),names=[stringSequenceFile()?.name,stringAliasesFile()?.name].filter(Boolean);
            picker.classList.toggle('has-file',names.length>0);
            picker.querySelector('.string-file-name').textContent=names.length?names.join(' · '):'No files selected';
            document.getElementById('stringFilesStatus').textContent=invalid?'Choose STRING .fa sequences and .txt aliases files with the expected names.':
                names.length===1?'Choose the other STRING file as well.':'';
            cancelStringMatching();updateFindMatchesReady();
            if(aliasesChanged)loadPreferredNames();
        }
        function currentStringReferenceKey() {
            return document.getElementById('pdbInput1').value.trim().toUpperCase().replace(/\s*,\s*/g, ',');
        }
        function loadPreferredNames() {
            cancelStringMatching();
            preferredNamesJob?.terminate();preferredNamesJob=null;preferredNames.clear();
            const file=stringAliasesFile();
            const status=document.getElementById('stringAliasStatus');
            stringAliasStatusReference = currentStringReferenceKey();
            preferredNamesState=file?'loading':'';
            status.textContent=file?'Reading preferred names from aliases…':'';
            syncStringMatchStatusVisibility();
            updatePreferredNameCells();
            if(!file)return;
            const url=URL.createObjectURL(new Blob([`(${preferredNamesWorker.toString()})();`],{type:'text/javascript'}));
            let worker;
            try {worker=new Worker(url);} catch(error){preferredNamesState='error';status.textContent=error.message;syncStringMatchStatusVisibility();updatePreferredNameCells();return;}
            finally {URL.revokeObjectURL(url);}
            preferredNamesJob=worker;
            const finish=(data)=>{
                if(preferredNamesJob!==worker)return;
                worker.terminate();preferredNamesJob=null;
                preferredNamesState=data.error?'error':'ready';
                if(!data.error)preferredNames=new Map(data.entries);
                status.textContent=data.error?`Could not read preferred names: ${data.error}`:'Preferred names loaded.';
                syncStringMatchStatusVisibility();
                updatePreferredNameCells();
            };
            worker.onmessage=({data})=>finish(data);
            worker.onerror=event=>finish({error:event.message||'Alias processing failed.'});
            worker.postMessage(file);
        }
        function preferredNameForAlignment(res) {
            const raw=res.atoms2?.[0]?.sourcePdbId || res.c2 || '';
            const id=raw.toUpperCase().replace(/^AF[-_]/,'').replace(/[-_]F\d+$/,'');
            return preferredNames.get(raw) || preferredNames.get(id) || null;
        }
        function updatePreferredNameCells() {
            const show=Boolean(stringAliasesFile());
            document.getElementById('preferredNameHeader').classList.toggle('hidden',!show);
            document.querySelectorAll('[data-preferred-name-row]').forEach(cell=>{
                cell.classList.toggle('hidden',!show);
                const res=alignmentResults[Number(cell.dataset.preferredNameRow)];
                const record=res?preferredNameForAlignment(res):null;
                cell.textContent=record?.name || (preferredNamesState==='loading'?'Loading…':'—');
                cell.title=record?.source || (preferredNamesState==='error'?'Alias file could not be read':'No preferred name found');
            });
        }
        function renderStringMatchResults(matches) {
            const container=document.getElementById('stringMatchResults');container.replaceChildren();
            document.getElementById('downloadStringMatchesBtn')?.classList.toggle('hidden', !matches.length);
            const table=document.createElement('table');table.className='w-full text-left text-xs';
            const thead=document.createElement('thead'),head=document.createElement('tr');
            head.className='bg-slate-950/80 text-slate-400 uppercase tracking-wider text-[11px] border-b border-slate-800';
            for(const label of ['Reference PDB chain','STRING protein','SW score','UniProt accession','Alias source','Notes']) {
                const th=document.createElement('th');th.className='py-3 px-4';th.scope='col';th.textContent=label;head.appendChild(th);
            }
            thead.appendChild(head);table.appendChild(thead);
            const tbody=document.createElement('tbody');tbody.className='divide-y divide-slate-800/60 font-mono';
            for(const match of matches) {
                const row=document.createElement('tr');row.className='hover:bg-slate-900/60 transition border-b border-slate-800/40';
                const notes=[];
                if(!match.protein)notes.push('No positive-scoring match');
                else if(!match.accession)notes.push('No eligible UniProt accession; nothing added');
                if(match.ties>1)notes.push(`${match.ties} tied best scores; selected by STRING ID`);
                if(match.aliasCount>1)notes.push(`${match.aliasCount} eligible aliases; selected first alphabetically`);
                const values=[match.chain,match.protein||'—',match.score,match.accession||'—',match.accession?match.source:'—',notes.join('; ')||'—'];
                values.forEach((value,index)=>{const td=document.createElement('td');td.className='py-2.5 px-4 '+(index===0?'font-bold text-sky-400':index===3?'font-bold text-teal-400':'text-slate-300');td.textContent=String(value);row.appendChild(td);});
                tbody.appendChild(row);
            }
            table.appendChild(tbody);container.appendChild(table);
            syncStringMatchStatusVisibility();
        }

        function syncStringMatchStatusVisibility() {
            const reference = currentStringReferenceKey();
            for (const [id, loadedReference] of [['stringAliasStatus',stringAliasStatusReference],['stringMatchStatus',stringMatchStatusReference]]) {
                const status = document.getElementById(id);
                status?.classList.toggle('hidden', !status.textContent || loadedReference !== reference);
            }
        }

        function hideStringMatchResults() {
            document.getElementById('stringMatchResults')?.replaceChildren();
            document.getElementById('downloadStringMatchesBtn')?.classList.add('hidden');
            syncStringMatchStatusVisibility();
        }

        function appendStringUniProtIds(value, matches) {
            const existing=parseModelInputs(value);
            const added=[];
            for(const match of matches)if(match.accession&&!added.includes(match.accession)) added.push(match.accession);
            if(!added.length)return {value,added};
            // STRING matches are authoritative: replace IDs while retaining manually entered sequences/FASTA.
            const preserved=existing.filter(e=>e.sequence).map(e=>e.sequence);
            const updated=added.concat(preserved).join(', ');
            return {value:updated,added};
        }

        let stringMatchJob = null;
        let findMatchesWasReady = false;
        function updateFindMatchesReady() {
            const id = document.getElementById('pdbInput1').value.trim().toUpperCase();
            const ready = (selectedReferencePdbIds().length > 0 || Boolean(uploadedStructureFiles.reference && id === uploadedStructureFiles.reference.inputValue))
                && Boolean(stringSequenceFile())
                && Boolean(stringAliasesFile());
            const button = document.getElementById('findStringMatchesBtn');
            if (ready && !findMatchesWasReady) {
                button.classList.remove('ready-glow');
                void button.offsetWidth;
                button.classList.add('ready-glow');
            } else if (!ready) button.classList.remove('ready-glow');
            findMatchesWasReady = ready;
        }
        function updateStringFileStyle(input) {
            const picker = input.closest('.string-file-picker');
            picker.classList.toggle('has-file', Boolean(input.files?.length));
            picker.querySelector('.string-file-name').textContent = input.files?.[0]?.name || 'No file selected';
            updateFindMatchesReady();
        }
        function cancelStringMatching() {
            if(stringMatchJob) {stringMatchJob.worker.terminate();stringMatchJob.reject(new Error('Matching cancelled because an input changed.'));stringMatchJob=null;}
        }
        async function findStringReferenceMatches() {
            const button=document.getElementById('findStringMatchesBtn'), status=document.getElementById('stringMatchStatus');
            const result=document.getElementById('stringMatchResults');
            const fasta=stringSequenceFile(), aliases=stringAliasesFile();
            const referenceInput=document.getElementById('pdbInput1').value;
            stringMatchStatusReference = currentStringReferenceKey();
            status.textContent = 'Loading reference chains…';
            button.disabled=true; result.textContent=''; syncStringMatchStatusVisibility();
            const alphaFoldInput = document.getElementById('pdbInput2');
            alphaFoldInput.value = '';
            alphaFoldInput.classList.remove('string-id-glow');
            updateBuildButtonState();
            try {
                const fa=fasta?.name.match(/^(\d+)\.protein\.sequences\.v([\d.]+)\.fa$/i);
                const al=aliases?.name.match(/^(\d+)\.protein\.aliases\.v([\d.]+)\.txt$/i);
                if(!fa || !al)throw new Error('Choose both STRING files: [taxon].protein.sequences.v[version].fa and [taxon].protein.aliases.v[version].txt.');
                if(fa[1]!==al[1] || fa[2]!==al[2])throw new Error('The two STRING files must have the same taxon ID and version.');
                status.textContent='Loading reference chains…';
                const entries=modelInputEntries(referenceInput,'reference');
                if(!entries.length)throw new Error('Enter a reference PDB ID first.');
                const files=await Promise.all(entries.map(entry=>loadModelInput(entry,false)));
                const inputsUnchanged=()=>document.getElementById('pdbInput1').value===referenceInput && stringSequenceFile()===fasta && stringAliasesFile()===aliases;
                if(!inputsUnchanged())throw new Error('Inputs changed; press Find matches again.');
                const queries=files.flatMap(file=>Object.entries(file.parsed.chains).filter(([,atoms])=>atoms[0]?.entityType==='protein').map(([chain,atoms])=>({chain:`${file.pdbId}: ${chain}`,sequence:atoms.map(a=>a.singleChar).join('')}))).filter(q=>q.sequence.length);
                if(!queries.length)throw new Error('No protein chains found in the reference.');
                const url=URL.createObjectURL(new Blob([`(${stringMatchingWorker.toString()})();`],{type:'text/javascript'}));
                let worker;
                try {worker=new Worker(url);} finally {URL.revokeObjectURL(url);}
                let response;
                try {
                    response=await new Promise((resolve,reject)=>{
                        stringMatchJob={worker,reject};
                        worker.onmessage=({data})=>{if(data.progress)status.textContent=data.progress;else if(data.error)reject(new Error(data.error));else resolve(data);};
                        worker.onerror=event=>reject(new Error(event.message || 'Sequence matching worker failed.'));
                        worker.postMessage({sequencesFile:fasta,aliasesFile:aliases,queries,taxon:fa[1],matrix:BLOSUM62_VALUES,alphabet:BLOSUM62_ALPHABET,gapOpen:alignmentGapOpen,gapExtend:alignmentGapExtend});
                    });
                } finally {worker.terminate();stringMatchJob=null;}
                if(!inputsUnchanged())throw new Error('Inputs changed; press Find matches again.');
                const input=document.getElementById('pdbInput2');
                const {value, added}=appendStringUniProtIds(input.value,response.matches);
                if(added.length) {
                    input.value=value;
                    resizeStructureIdInputs();
                    input.classList.remove('string-id-glow');
                    void input.offsetWidth;
                    input.classList.add('string-id-glow');
                    updateBuildButtonState();
                }
                status.textContent=`Searched ${response.count.toLocaleString()} proteins. Loaded ${added.length} unique UniProt ID(s).`;
                renderStringMatchResults(response.matches);
                if (added.length) void loadModelPair(document.getElementById('pdbInput1').value.trim(), input.value.trim().toUpperCase());
            } catch(error) {status.textContent=error.message;syncStringMatchStatusVisibility();}
            finally {button.disabled=false;}
        }

// stringSpeciesMatching.js end

// modelInput.js start
        async function resolveUniProtInput(entry, signal) {
            const accession = entry.id;
            const response = await fetch(`https://alphafold.ebi.ac.uk/api/prediction/${encodeURIComponent(accession)}`, {signal});
            if (!response.ok && response.status !== 404) {
                throw new Error(`AlphaFold lookup for ${accession} failed (HTTP ${response.status}). Please retry.`);
            }
            const models = response.ok ? await response.json() : [];
            if (!Array.isArray(models)) throw new Error(`Unexpected AlphaFold response for ${accession}. Please retry.`);
            const model = models.find(m => m.pdbUrl || m.cifUrl);
            if (model) {
                const file = await fetch(trustedAlphaFoldUrl(model.pdbUrl || model.cifUrl), {signal});
                if (!file.ok) throw new Error(`Could not download AlphaFold model for ${accession} (HTTP ${file.status}). Please retry.`);
                return { text: await file.text(), sequence: null };
            }
            if (models.length) throw new Error(`AlphaFold returned no downloadable coordinates for ${accession}.`);
            const sequenceResponse = await fetch(`https://rest.uniprot.org/uniprotkb/${encodeURIComponent(accession)}.fasta`, {signal});
            if (!sequenceResponse.ok) throw new Error(`No AlphaFold model found for ${accession}; UniProt sequence lookup failed (HTTP ${sequenceResponse.status}). Please check the accession.`);
            const fasta = await sequenceResponse.text();
            if (!fasta.trim().startsWith('>')) throw new Error(`UniProt returned an invalid sequence for ${accession}.`);
            const records = parseModelInputs(fasta);
            if (records.length !== 1 || !records[0].sequence) throw new Error(`Expected one UniProt sequence for ${accession}.`);
            return { text: sequenceToPdb(records[0].sequence), sequence: records[0].sequence };
        }

        async function loadModelInput(entry,includeOther=false,signal) {
            let sequence = entry.sequence;
            let text;
            let alphaFoldCoordinates = Boolean(entry.uploadFile);
            if (entry.uploadFile) {
                text = await entry.uploadFile.text();
                if (!text.trim()) throw new Error(`Uploaded structure ${entry.id} is empty.`);
            }
            // UniProt accessions (including explicit isoforms) are distinct from PDB IDs.
            const isUniProt = /^(?:[OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9](?:[A-Z][A-Z0-9]{2}[0-9]){1,2})(?:-[0-9]+)?$/.test(entry.id);
            if (entry.uploadFile) { /* Use the selected local coordinates. */ }
            else if (!sequence && isUniProt) {
                const resolved = await resolveUniProtInput(entry,signal);
                text = resolved.text;
                sequence = resolved.sequence;
                alphaFoldCoordinates = !resolved.sequence;
            } else text = sequence ? sequenceToPdb(sequence) : await fetchPdbData(entry.id,signal);
            if (signal?.aborted) throw new DOMException('Model build cancelled', 'AbortError');
            if (/^AF[-_]/i.test(entry.id)) alphaFoldCoordinates = true;
            const format = /^(?:\uFEFF)?\s*data_/m.test(text) ? 'mmcif' : 'pdb';
            const parsed = format === 'mmcif' ? parseMmCifCalpha(text,includeOther) : parsePDBCalpha(text,includeOther);
            if (!parsed.allAtoms.length) throw new Error(includeOther?`No coordinate atoms found in ${entry.id}.`:`No protein or nucleotide residues found in ${entry.id}.`);
            assignSecondaryStructure(parsed.chains);
            if (sequence) parsed.allAtoms.forEach((atom, i) => {
                atom.singleChar = sequence[i];
                atom.sequenceOnly = true;
            });
            if (!alphaFoldCoordinates) parsed.allAtoms.forEach(atom => { atom.plddt = null; });
            return { pdbId: entry.id, parsed, text, format, sequenceOnly: Boolean(sequence), sequenceFallback: Boolean(sequence && !entry.sequence), alphaFoldCoordinates };
        }

        function buildModel2FromFiles(fileResults) {
            const chains = {};
            const caAtoms = [];
            const files = [];

            fileResults.forEach((fr, fileIndex) => {
                const chainKeysInFile = Object.keys(fr.parsed.chains);
                const singleChainFile = chainKeysInFile.length === 1;

                chainKeysInFile.forEach(origChainId => {
                    const atoms = fr.parsed.chains[origChainId];
                    let baseKey = singleChainFile ? fr.pdbId : `${fr.pdbId}.${origChainId}`;
                    let key = baseKey, suffix = 2;
                    while (chains.hasOwnProperty(key)) { key = `${baseKey}_${suffix}`; suffix++; }

                    atoms.forEach(a => {
                        a.groupKey = key;
                        a.fileIndex = fileIndex;
                        a.sourcePdbId = fr.pdbId;
                    });

                    chains[key] = atoms;
                    caAtoms.push(...atoms);
                });

                files.push({ pdbId: fr.pdbId, fileIndex });
            });

            return { chains, caAtoms, files };
        }

// modelInput.js end

// pdbFetching.js start
        // ==========================================
        // 5. PDB FETCHING & DATA LOADING
        // ==========================================
        async function fetchPdbData(cleanId,signal) {
            let pdbText = null;
            const extractAcc = cleanId.replace(/^AF[-_]?/i, '').replace(/[-_]?F\d+$/i, '').trim();
            const isLikelyUniProt = cleanId.startsWith('AF') || cleanId.length > 4 || !/^[0-9][A-Z0-9]{3}$/i.test(cleanId);

            if (isLikelyUniProt) {
                try {
                    const afResponse = await fetch(`https://alphafold.ebi.ac.uk/api/prediction/${extractAcc}`, {signal});
                    if (afResponse.ok) {
                        const afData = await afResponse.json();
                        if (Array.isArray(afData) && afData.length > 0 && afData[0].pdbUrl) {
                            const fileResp = await fetch(trustedAlphaFoldUrl(afData[0].pdbUrl), {signal});
                            if (fileResp.ok) pdbText = await fileResp.text();
                        }
                    }
                } catch (e) { if (signal?.aborted) throw e; console.warn('AF fetch notice:', e); }
            }

            if (!pdbText) {
                // RCSB's biological assembly 1 contains the generated, functional
                // complex. Fall back to the deposited asymmetric unit when an
                // assembly file is unavailable for this entry.
                const candidateUrls = [
                    `https://files.rcsb.org/download/${cleanId}-assembly1.cif`,
                    `https://files.rcsb.org/download/${cleanId}.pdb`,
                    `https://www.ebi.ac.uk/pdbe/entry-files/download/pdb${cleanId.toLowerCase()}.ent`,
                    `https://files.rcsb.org/download/${cleanId}.cif`,
                    `https://www.ebi.ac.uk/pdbe/entry-files/download/${cleanId.toLowerCase()}.cif`
                ];
                for (let i = 0; i < candidateUrls.length; i++) {
                    const url = candidateUrls[i];
                    try {
                        const response = await fetch(url,{signal});
                        if (response.ok) {
                            const text = await response.text();
                            if (text && (text.includes('_atom_site.') || /^ATOM  /m.test(text))) { pdbText = text; break; }
                        }
                    } catch (e) { if (signal?.aborted) throw e; }
                }
            }

            if (!pdbText) throw new Error(`Could not fetch structure '${cleanId}'. Please check ID. Maybe you've confused a 0 (zero) for an O?`);
            return pdbText;
        }

// pdbFetching.js end

// matrixRendering.js start
        // ==========================================
        // 6. OFFSCREEN CANVAS ACCELERATED RENDERING
        // ==========================================
        // Instead of calling ctx.fillRect millions of times, we write directly to a 32-bit Uint32Array
        // ImageData buffer, then blit with GPU-accelerated drawImage! 100x-500x faster!
        function updateMatrixViewport(cache, N, canvas, scale, offX, offY) {
            // Use a square residue tile covering the visible area, plus a cell margin.
            const extent = Math.min(N, Math.max(1, Math.ceil(Math.max(canvas.width, canvas.height) / Math.max(scale, 0.000001)) + 2));
            const x = Math.max(0, Math.min(N - extent, Math.floor(-offX / scale) - 1));
            const y = Math.max(0, Math.min(N - extent, Math.floor(-offY / scale) - 1));
            const key = `${N}:${x}:${y}:${extent}`;
            if (cache.viewportKey !== key) {
                cache.viewportKey = key;
                cache.viewport = { x, y, extent };
                cache.dirty = true;
            }
            return extent;
        }
        let matrixDataVersion = 0;
        function matrixContentKey(kind, extra = '') {
            return [matrixDataVersion, modelBuildGeneration, kind, extra, currentPalette,
                morphAlpha, model1Influence, model2Influence, referenceAssembly ? referenceInfluences.join(',') : '', morphColorMode,
                showSpringCutoff, springCutoffVal, diffMatrixMode, selectedPairKey].join(':');
        }
        function drawMatrixViewport(ctx, cache, scale, offX, offY) {
            if (cache.overview) ctx.drawImage(cache.overview, offX, offY, cache.overviewSize * scale, cache.overviewSize * scale);
            const view = cache.renderedViewport;
            if (view) ctx.drawImage(cache.canvas, offX + view.x * scale, offY + view.y * scale, view.extent * scale, view.extent * scale);
        }
        function drawLinkedMatrixSelection(ctx,scale,offX,offY,kind,model=null) {
            if (!linkedSelection||linkedSelection.kind==='lipid') return;
            if(linkedSelection.kind==='pair'){
                const axisIndex=nodeIndex=>{
                    const node=physicsNodes[nodeIndex];if(!node)return -1;
                    if(kind==='single'){
                        const atom=validationAtom(node,model===modelData1?'reference':'af');
                        const atoms=model.currentChain==='ALL'?model.caAtoms:model.chains[model.currentChain]||[];
                        return atoms.indexOf(atom);
                    }
                    if(kind==='diff'){
                        const res=alignmentResults[selectedPairKey];
                        if(res!==node.res)return -1;
                        return res.alignedPairs.findIndex(pair=>pair.idx1===node.idx1&&pair.idx2===node.idx2);
                    }
                    return morphMatrixPositions.findIndex(pos=>pos.res===node.res&&pos.pair.idx1===node.idx1&&pos.pair.idx2===node.idx2);
                };
                const i=axisIndex(linkedSelection.i),j=axisIndex(linkedSelection.j);
                if(i>=0&&j>=0){ctx.save();ctx.strokeStyle='#ffffff';ctx.lineWidth=2.5;
                    ctx.shadowColor=document.body.classList.contains('light-mode')?'rgba(15,23,42,.9)':'rgba(255,255,255,.9)';ctx.shadowBlur=9;
                    for(const [a,b] of [[i,j],[j,i]]){ctx.beginPath();ctx.arc(offX+(a+.5)*scale,offY+(b+.5)*scale,Math.max(5,Math.min(12,scale*.7)),0,Math.PI*2);ctx.stroke();}
                    ctx.restore();}
                return;
            }
            let index=-1;
            let start=-1,end=-1;
            const matches=(res,atom)=>res?.c1===linkedSelection.chain&&atom&&(linkedSelection.mode==='chain'||atom===linkedSelection.referenceAtom||atom===linkedSelection.alphaAtom);
            if (kind==='single') {
                const atoms=model.currentChain==='ALL'?model.caAtoms:model.chains[model.currentChain]||[];
                const relevant=alignmentResults.filter(res=>res.c1===linkedSelection.chain);
                const selectedAtoms=new Set(relevant.flatMap(res=>model===modelData1?res.atoms1:res.atoms2));
                index=atoms.findIndex(atom=>selectedAtoms.has(atom)&&(linkedSelection.mode==='chain'||atom===linkedSelection.referenceAtom||atom===linkedSelection.alphaAtom));
                if (linkedSelection.mode==='chain'&&index>=0) { start=index;end=atoms.findLastIndex(atom=>selectedAtoms.has(atom))+1; }
            } else if (kind==='diff') {
                const res=alignmentResults[selectedPairKey];
                index=res?.alignedPairs.findIndex(pair=>matches(res,pair.idx1!==null?res.atoms1[pair.idx1]:pair.idx2!==null?res.atoms2[pair.idx2]:null))??-1;
                if (linkedSelection.mode==='chain'&&res?.c1===linkedSelection.chain) { start=0;end=res.alignedPairs.length; }
            } else if (kind==='morph') {
                index=morphMatrixPositions.findIndex(pos=>matches(pos.res,pos.pair.idx1!==null?pos.res.atoms1[pos.pair.idx1]:pos.pair.idx2!==null?pos.res.atoms2[pos.pair.idx2]:null));
                if (linkedSelection.mode==='chain') { const block=morphMatrixBlocks.find(item=>item.c1===linkedSelection.chain);if(block){start=block.offset;end=start+block.length;} }
            }
            ctx.save();ctx.strokeStyle='#facc15';ctx.lineWidth=2.5;
            if (linkedSelection.mode==='chain'&&start>=0&&end>start) {
                const pos=offX+start*scale, y=offY+start*scale,extent=(end-start)*scale;
                if(kind==='diff'){
                    ctx.fillStyle=getChainColor(linkedSelection.chain,morphMatrixBlocks.map(block=>block.c1));
                    ctx.fillRect(pos,offY-7,extent,5);ctx.fillRect(offX-7,y,5,extent);
                }
                ctx.strokeRect(pos,offY-8,extent,7);ctx.strokeRect(offX-8,y,7,extent);
            } else if(index>=0) {
                const x=offX+(index+.5)*scale,y=offY+(index+.5)*scale;
                ctx.beginPath();ctx.arc(x,y,Math.max(5,Math.min(12,scale*.7)),0,Math.PI*2);ctx.stroke();
            }
            ctx.restore();
        }
        function saveMatrixOverview(cache, key, N) {
            cache.overview ||= document.createElement('canvas');
            cache.overview.width = cache.canvas.width;
            cache.overview.height = cache.canvas.height;
            cache.overview.getContext('2d').drawImage(cache.canvas, 0, 0);
            cache.overviewKey = key;
            cache.overviewSize = N;
            if(cache===offscreenCaches.morph)document.getElementById('morphMatrixLoading')?.classList.add('hidden');
        }
        // Show a bounded full-matrix sample immediately; refine exact extrema independently of navigation.
        async function fullMatrixRange(cache, key, N, valueAt, checkpoint) {
            let state = cache.rangeState;
            if (state?.key === key && state.bounds) return state.bounds;
            if (!state || state.key !== key) {
                state = { key, i: 0, j: 0, min: Infinity, max: -Infinity };
                cache.rangeState = state;
            }
            const boundsOf = (min, max) => {
                min = Number.isFinite(min) ? min : 0;
                return { min, max: Number.isFinite(max) && max > min ? max : min + 1 };
            };
            const samples = Math.min(N, 192);
            let min = Infinity, max = -Infinity;
            for (let row = 0; row < samples; row++) {
                if (!await checkpoint()) return null;
                const i = samples > 1 ? Math.round(row * (N - 1) / (samples - 1)) : 0;
                for (let col = row; col < samples; col++) {
                    const j = samples > 1 ? Math.round(col * (N - 1) / (samples - 1)) : 0;
                    const value = valueAt(i, j);
                    if (value !== null && Number.isFinite(value) && value >= 0) { min = Math.min(min, value); max = Math.max(max, value); }
                }
            }
            if (cache.rangeState !== state) return null;
            state.bounds = boundsOf(min, max);
            if (N <= samples) { state.exact = true; return state.bounds; }
            // Timed chunks never gate the initial image or get restarted by zoom/pan.
            const refine = () => {
                if (cache.rangeState !== state) return;
                const start = performance.now();
                do {
                    for (let work = 0; work < 256 && state.i < N; work++) {
                        const value = valueAt(state.i, state.j);
                        if (value !== null && Number.isFinite(value) && value >= 0) {
                            state.min = Math.min(state.min, value); state.max = Math.max(state.max, value);
                        }
                        if (++state.j >= N) { state.i++; state.j = state.i; }
                    }
                } while (state.i < N && performance.now() - start < 3);
                if (state.i < N) { setTimeout(refine, 30); return; }
                const exact = boundsOf(state.min, state.max);
                const changed = exact.min !== state.bounds.min || exact.max !== state.bounds.max;
                state.bounds = exact; state.exact = true;
                if (changed) {
                    cache.overviewKey = null;
                    cache.dirty = true;
                    requestAnimationFrame(() => { drawIndividualMatrices(); drawDifferenceMatrix(); drawMorphMatrix(); });
                }
            };
            setTimeout(refine, 250);
            return state.bounds;
        }

        function scheduleMatrixRender(cache, render, redraw) {
            if (cache.pendingRender && !cache.dirty) return;
            clearTimeout(cache.renderTimer);
            const token = (cache.renderToken || 0) + 1;
            cache.renderToken = token;
            cache.dirty = false;
            cache.pendingRender = true;
            // Navigation redraws the last completed image immediately; refinement waits briefly.
            cache.renderTimer = setTimeout(async () => {
                let lastYield = performance.now();
                const valid = () => cache.renderToken === token && !cache.dirty;
                const checkpoint = async () => {
                    if (!valid()) return false;
                    if (performance.now() - lastYield >= 4) {
                        await new Promise(resolve => setTimeout(resolve, 0));
                        lastYield = performance.now();
                    }
                    return valid();
                };
                try {
                    await render(checkpoint, valid);
                } catch (error) {
                    console.error('Matrix refinement failed:', error);
                } finally {
                    if (cache.renderToken === token) {
                        if(cache===offscreenCaches.morph)document.getElementById('morphMatrixLoading')?.classList.add('hidden');
                        cache.pendingRender = false;
                        requestAnimationFrame(redraw);
                    }
                }
            }, cache.overview ? 120 : 0);
        }

        async function updateOffscreenMatrix(cacheObj, atoms, chainKey, modelData, checkpoint, valid, overviewPass = false) {
            const N = atoms.length;
            const contentKey = matrixContentKey('individual', chainKey);
            if (!overviewPass && cacheObj.overviewKey !== contentKey) {
                await updateOffscreenMatrix(cacheObj, atoms, chainKey, modelData, checkpoint, valid, true);
                if (!valid() || cacheObj.overviewKey !== contentKey) return;
                requestAnimationFrame(drawIndividualMatrices);
                if (cacheObj.viewport?.extent === N) return;
            }
            const view = overviewPass ? { x: 0, y: 0, extent: N } : cacheObj.viewport || { x: 0, y: 0, extent: N };
            const S = Math.min(view.extent, 1024);
            const rowAt = pixel => view.y + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));
            const colAt = pixel => view.x + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));
            if (N === 0) return;

            PerfTracker.start(`offscreen_${chainKey}`);


            const imgData = cacheObj.ctx.createImageData(S, S);
            const data32 = new Uint32Array(imgData.data.buffer);
            const matrix = getOrComputeDistanceMatrix(modelData, chainKey, atoms);
            const palTable = PALETTE_TABLES_32[currentPalette] || PALETTE_TABLES_32.viridis;

            // Background color for non-comparable cells: #1e293b (A=255, B=59, G=41, R=30)
            const blankColor = (255 << 24) | (59 << 16) | (41 << 8) | 30;

            const bounds = await fullMatrixRange(cacheObj, contentKey, N, (i,j) => matrix[i * N + j], checkpoint);
            if (!bounds || !valid()) return;
            const minVal = bounds.min, maxVal = bounds.max;
            const range = maxVal - minVal;

            for (let pixelI = 0; pixelI < S; pixelI++) {
                if (!await checkpoint()) return;
                const i = rowAt(pixelI);
                const rowOffset = pixelI * S;
                for (let pixelJ = 0; pixelJ < S; pixelJ++) {
                    const j = colAt(pixelJ);
                    const dist = matrix[i * N + j];
                    if (dist < 0) {
                        data32[rowOffset + pixelJ] = blankColor;
                    } else {
                        // Map distance relative to this matrix's min and max values
                        const normByte = Math.max(0, Math.min(255, Math.floor(((dist - minVal) / range) * 255)));
                        data32[rowOffset + pixelJ] = palTable[normByte];
                    }
                }
            }

            if (!valid()) return;
            cacheObj.canvas.width = S;
            cacheObj.canvas.height = S;
            cacheObj.ctx.putImageData(imgData, 0, 0);
            cacheObj.renderedViewport = { ...view };
            if (overviewPass) saveMatrixOverview(cacheObj, contentKey, N);
            cacheObj.dirty = false;
            cacheObj.chain = chainKey;
            const elapsed = PerfTracker.end(`offscreen_${chainKey}`);
            // console.log(`[StringScape Homology Modeller Perf] Offscreen buffer generated for ${chainKey} in ${elapsed.toFixed(1)}ms`);
        }

        function updateMatrixResolutionNotice(id, size) {
            document.getElementById(id).classList.toggle('hidden', size <= 1024);
        }

        function saveBlob(blob, filename) {
            if (!blob) throw new Error('Could not encode the image.');
            const url=URL.createObjectURL(blob), link=document.createElement('a');
            link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();
            setTimeout(()=>URL.revokeObjectURL(url),60000);
        }
        function canvasPngBlob(canvas) {
            return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('PNG encoding failed.')),'image/png'));
        }
        function downloadTableCsv(containerId, filename) {
            const container=document.getElementById(containerId);
            const table=container?.closest('table')||container?.querySelector('table');
            if(!table)return;
            const rows=[...table.querySelectorAll('tr')].map(row=>[...row.children]
                .filter(cell=>!cell.classList.contains('hidden')&&!cell.querySelector('button')&&cell.textContent.trim()!=='Action')
                .map(cell=>'"'+cell.textContent.trim().replace(/"/g,'""')+'"'));
            saveBlob(new Blob(['\ufeff'+rows.map(row=>row.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),filename);
        }
        async function downloadMatrixPng(kind, resolution) {
            try {
                const cache=kind==='pdb'?offscreenCaches.PDB:kind==='af'?offscreenCaches.AF:offscreenCaches[kind];
                const model=kind==='pdb'?modelData1:kind==='af'?modelData2:null;
                const atoms=model?(model.currentChain==='ALL'?model.caAtoms:model.chains[model.currentChain]||[]):null;
                const result=kind==='diff'?alignmentResults[selectedPairKey]:null;
                const N=atoms?.length??(kind==='diff'?result?.alignedPairs.length:morphMatrixSize);
                if(!N)throw new Error('Load a matrix before downloading it.');
                const filename=`${kind}-matrix-${resolution}-${N}x${N}.png`;
                if(resolution==='low') {
                    const key=matrixContentKey(model?'individual':kind,model?model.currentChain:kind==='diff'?selectedPairKey:'');
                    if(!cache.overview||cache.overviewKey!==key) {
                        const checkpoint=async()=>true,valid=()=>true;
                        if(model)await updateOffscreenMatrix(cache,atoms,model.currentChain,model,checkpoint,valid,true);
                        else if(kind==='diff')await updateOffscreenDiffMatrix(result,checkpoint,valid,true);
                        else await updateOffscreenMorphMatrix(checkpoint,valid,true);
                    }
                    if(!cache.overview)throw new Error('Matrix overview is not ready.');
                    saveBlob(await canvasPngBlob(cache.overview),filename);
                    return;
                }
                // One output pixel per actual cell; row strips limit temporary image memory.
                if(N>8192)throw new Error(`This ${N} × ${N} matrix exceeds the browser's single-PNG canvas limit. Zoomed tiles remain available in the viewer.`);
                const canvas=document.createElement('canvas');canvas.width=N;canvas.height=N;
                const context=canvas.getContext('2d');
                if(!context)throw new Error('Could not allocate the PNG canvas.');
                const blank=(255<<24)|(59<<16)|(41<<8)|30;
                const palette=PALETTE_TABLES_32[currentPalette]||PALETTE_TABLES_32.viridis;
                const matrix=model?getOrComputeDistanceMatrix(model,model.currentChain,atoms):null;
                const mat1=result?getOrComputeDistanceMatrix(modelData1,result.c1,result.atoms1):null;
                const mat2=result?getOrComputeDistanceMatrix(modelData2,result.c2,result.atoms2):null;
                let min=0,max=1;
                if(model) {
                    min=Infinity;max=-Infinity;
                    for(let i=0;i<N;i++){
                        for(let j=i;j<N;j++){
                            const value=matrix[i*N+j];
                            if(value>=0&&Number.isFinite(value)){min=Math.min(min,value);max=Math.max(max,value);}
                        }
                        if(i%16===0)await new Promise(resolve=>setTimeout(resolve,0));
                    }
                } else if(kind==='morph'&&morphColorMode!=='origin') {
                    min=Infinity;max=-Infinity;
                    for(let i=0;i<N;i++){for(let j=0;j<N;j++){const value=getMorphCellValue(morphMatrixPositions[i],morphMatrixPositions[j],morphAlpha)?.value;
                        if(Number.isFinite(value)){min=Math.min(min,value);max=Math.max(max,value);}}if(i%16===0)await new Promise(resolve=>setTimeout(resolve,0));}
                }
                if(!Number.isFinite(min)){min=0;max=1;}
                const range=Math.max(1e-9,max-min),norm=value=>Math.max(0,Math.min(255,Math.floor((value-min)/range*255)));
                for(let first=0;first<N;first+=32) {
                    const rows=Math.min(32,N-first),image=context.createImageData(N,rows),pixels=new Uint32Array(image.data.buffer);
                    for(let r=0;r<rows;r++){
                        const i=first+r;
                        for(let j=0;j<N;j++){
                            let color=blank;
                            if(model){const value=matrix[i*N+j];if(value>=0)color=palette[norm(value)];}
                            else if(result){
                                const a=result.alignedPairs[i],b=result.alignedPairs[j];
                                if(a.idx1!==null&&a.idx2!==null&&b.idx1!==null&&b.idx2!==null){
                                    const d1=mat1[a.idx1*result.atoms1.length+b.idx1],d2=mat2[a.idx2*result.atoms2.length+b.idx2];
                                    if(d1>=0&&d2>=0)color=diffMatrixMode==='diff'?diffTable32[Math.min(255,Math.floor(Math.abs(d1-d2)/10*255))]
                                        :j>=i?PALETTE_TABLES_32.viridis[Math.min(255,Math.floor(d1/40*255))]
                                        :PALETTE_TABLES_32.coolwarm[Math.min(255,Math.floor(d2/40*255))];
                                }
                            } else {
                                const cell=getMorphCellValue(morphMatrixPositions[i],morphMatrixPositions[j],morphAlpha);
                                if(cell){
                                    if(morphColorMode==='origin')color=referenceOriginColor(cell);
                                    else color=palette[norm(cell.value)];
                                    color=applyMorphOpacity(color,!showSpringCutoff||cell.value<=springCutoffVal?cell.mmsi:0);
                                }
                            }
                            pixels[r*N+j]=color;
                        }
                    }
                    context.putImageData(image,0,first);
                    await new Promise(resolve=>setTimeout(resolve,0));
                }
                saveBlob(await canvasPngBlob(canvas),filename);
                canvas.width=canvas.height=0;
            } catch(error){console.error('Matrix PNG export failed:',error);alert(error.message||'Could not export this matrix.');}
        }

        function renderSingleMatrixFast(ctx, canvas, modelData, scale, offX, offY, hoverCell, cacheObj) {
            if (!ctx || !modelData) return;
            const atoms = modelData.currentChain === 'ALL' ? modelData.caAtoms : (modelData.chains[modelData.currentChain] || []);
            const N = atoms.length;
            updateMatrixResolutionNotice(modelData === modelData1 ? 'PDBResolutionNotice' : 'AFResolutionNotice', updateMatrixViewport(cacheObj, N, canvas, scale, offX, offY));
            if (N === 0) return;

            const t0 = performance.now();
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = document.body.classList.contains('light-mode') ? '#f8fafc' : '#020617';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const chainKey = modelData.currentChain;
            if (cacheObj.dirty || cacheObj.chain !== chainKey) {
                scheduleMatrixRender(cacheObj, (checkpoint, valid) => updateOffscreenMatrix(cacheObj, atoms, chainKey, modelData, checkpoint, valid), drawIndividualMatrices);
            }

            // Blit offscreen matrix in ONE single GPU draw call!
            ctx.imageSmoothingEnabled = false;
            drawMatrixViewport(ctx, cacheObj, scale, offX, offY);

            // Chain boundary indicator marks
            const allChains = Object.keys(modelData.chains);
            const segments = getChainSegments(atoms);
            if (segments.length > 0) {
                for (let s = 0; s < segments.length; s++) {
                    const seg = segments[s];
                    const color = getChainColor(seg.chainId, allChains);
                    const segStartX = offX + seg.start * scale;
                    const segStartY = offY + seg.start * scale;
                    const segWidth = seg.count * scale;

                    ctx.fillStyle = color;
                    ctx.fillRect(segStartX, offY - 7, segWidth, 5);
                    ctx.fillRect(offX - 7, segStartY, 5, segWidth);
                }

                ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
                ctx.lineWidth = 1;
                ctx.setLineDash([3, 3]);

                for (let k = 1; k < segments.length; k++) {
                    const boundaryIdx = segments[k].start;
                    const bx = offX + boundaryIdx * scale;
                    const by = offY + boundaryIdx * scale;
                    ctx.beginPath(); ctx.moveTo(bx, offY - 7); ctx.lineTo(bx, offY + N * scale); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(offX - 7, by); ctx.lineTo(offX + N * scale, by); ctx.stroke();
                }
                ctx.setLineDash([]);
            }

            // Highlight hovered cell
            if (hoverCell && hoverCell.i >= 0 && hoverCell.i < N && hoverCell.j >= 0 && hoverCell.j < N) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.strokeRect(offX + hoverCell.j * scale, offY + hoverCell.i * scale, Math.max(1, scale), Math.max(1, scale));
            }
            drawLinkedMatrixSelection(ctx,scale,offX,offY,'single',modelData);

            PerfTracker.metrics.matrixDrawTime = performance.now() - t0;
        }

        function drawIndividualMatrices() {
            renderSingleMatrixFast(ctx1, canvas1, modelData1, scale1, offX1, offY1, hoverCell1, offscreenCaches.PDB);
            renderSingleMatrixFast(ctx2, canvas2, modelData2, scale2, offX2, offY2, hoverCell2, offscreenCaches.AF);
        }

        // Offscreen Aligned Difference Matrix
        async function updateOffscreenDiffMatrix(res, checkpoint, valid, overviewPass = false) {
            const pairs = res.alignedPairs;
            const N = pairs.length;
            const contentKey = matrixContentKey('diff', selectedPairKey);
            if (!overviewPass && offscreenCaches.diff.overviewKey !== contentKey) {
                await updateOffscreenDiffMatrix(res, checkpoint, valid, true);
                if (!valid() || offscreenCaches.diff.overviewKey !== contentKey) return;
                requestAnimationFrame(drawDifferenceMatrix);
                if (offscreenCaches.diff.viewport?.extent === N) return;
            }
            const view = overviewPass ? { x: 0, y: 0, extent: N } : offscreenCaches.diff.viewport || { x: 0, y: 0, extent: N };
            const S = Math.min(view.extent, 1024);
            const rowAt = pixel => view.y + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));
            const colAt = pixel => view.x + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));
            if (N === 0) return;

            PerfTracker.start('offscreen_diff');


            const imgData = offscreenCaches.diff.ctx.createImageData(S, S);
            const data32 = new Uint32Array(imgData.data.buffer);
            const mat1 = getOrComputeDistanceMatrix(modelData1, res.c1, res.atoms1);
            const mat2 = getOrComputeDistanceMatrix(modelData2, res.c2, res.atoms2);
            const n1 = res.atoms1.length;
            const n2 = res.atoms2.length;

            const viridisTable = PALETTE_TABLES_32.viridis;
            const coolwarmTable = PALETTE_TABLES_32.coolwarm;
            const blankColor = (255 << 24) | (59 << 16) | (41 << 8) | 30; // #1e293b

            for (let pixelI = 0; pixelI < S; pixelI++) {
                if (!await checkpoint()) return;
                const i = rowAt(pixelI);
                const pairI = pairs[i];
                const rowOffset = pixelI * S;
                const idx1_i = pairI.idx1;
                const idx2_i = pairI.idx2;

                for (let pixelJ = 0; pixelJ < S; pixelJ++) {
                    const j = colAt(pixelJ);
                    const pairJ = pairs[j];
                    const idx1_j = pairJ.idx1;
                    const idx2_j = pairJ.idx2;

                    const valid1 = idx1_i !== null && idx1_j !== null;
                    const valid2 = idx2_i !== null && idx2_j !== null;

                    if (!valid1 || !valid2) {
                        data32[rowOffset + pixelJ] = blankColor;
                        continue;
                    }

                    const d1 = mat1[idx1_i * n1 + idx1_j];
                    const d2 = mat2[idx2_i * n2 + idx2_j];
                    if (d1 < 0 || d2 < 0) { data32[rowOffset + pixelJ] = blankColor; continue; }

                    if (diffMatrixMode === 'diff') {
                        const delta = Math.abs(d1 - d2);
                        const normByte = Math.min(255, Math.floor((delta / 10.0) * 255));
                        data32[rowOffset + pixelJ] = diffTable32[normByte];
                    } else {
                        if (j >= i) {
                            const normByte = Math.min(255, Math.floor((d1 / 40.0) * 255));
                            data32[rowOffset + pixelJ] = viridisTable[normByte];
                        } else {
                            const normByte = Math.min(255, Math.floor((d2 / 40.0) * 255));
                            data32[rowOffset + pixelJ] = coolwarmTable[normByte];
                        }
                    }
                }
            }

            if (!valid()) return;
            offscreenCaches.diff.canvas.width = S;
            offscreenCaches.diff.canvas.height = S;
            offscreenCaches.diff.ctx.putImageData(imgData, 0, 0);
            offscreenCaches.diff.renderedViewport = { ...view };
            if (overviewPass) saveMatrixOverview(offscreenCaches.diff, contentKey, N);
            offscreenCaches.diff.dirty = false;
            offscreenCaches.diff.pairKey = selectedPairKey;
            offscreenCaches.diff.mode = diffMatrixMode;
            PerfTracker.end('offscreen_diff');
        }

        function drawDifferenceMatrix() {
            if (!diffCtx || !alignmentResults.length || selectedPairKey === null) return;
            const res = alignmentResults[selectedPairKey];
            if (!res) return;

            const N = res.alignedPairs.length;
            updateMatrixResolutionNotice('diffResolutionNotice', updateMatrixViewport(offscreenCaches.diff, N, diffCanvas, diffScale, diffOffX, diffOffY));
            diffCtx.clearRect(0, 0, diffCanvas.width, diffCanvas.height);
            diffCtx.fillStyle = document.body.classList.contains('light-mode') ? '#f8fafc' : '#020617';
            diffCtx.fillRect(0, 0, diffCanvas.width, diffCanvas.height);

            if (offscreenCaches.diff.dirty || offscreenCaches.diff.pairKey !== selectedPairKey || offscreenCaches.diff.mode !== diffMatrixMode) {
                scheduleMatrixRender(offscreenCaches.diff, (checkpoint, valid) => updateOffscreenDiffMatrix(res, checkpoint, valid), drawDifferenceMatrix);
            }

            diffCtx.imageSmoothingEnabled = false;
            drawMatrixViewport(diffCtx, offscreenCaches.diff, diffScale, diffOffX, diffOffY);

            if (diffHoverCell && diffHoverCell.i >= 0 && diffHoverCell.i < N && diffHoverCell.j >= 0 && diffHoverCell.j < N) {
                diffCtx.strokeStyle = '#ffffff';
                diffCtx.lineWidth = 1.5;
                diffCtx.strokeRect(diffOffX + diffHoverCell.j * diffScale, diffOffY + diffHoverCell.i * diffScale, Math.max(1, diffScale), Math.max(1, diffScale));
            }
            drawLinkedMatrixSelection(diffCtx,diffScale,diffOffX,diffOffY,'diff');
        }

        // Fast Morph Matrix with 32-bit Typed Array Blitting
        async function updateOffscreenMorphMatrix(checkpoint, valid, overviewPass = false) {
            if (!morphMatrixSize) return;
            const N = morphMatrixSize;
            const contentKey = matrixContentKey('morph', '');
            if (!overviewPass && offscreenCaches.morph.overviewKey !== contentKey) {
                await updateOffscreenMorphMatrix(checkpoint, valid, true);
                if (!valid() || offscreenCaches.morph.overviewKey !== contentKey) return;
                requestAnimationFrame(drawMorphMatrix);
                if (offscreenCaches.morph.viewport?.extent === N) return;
            }
            const view = overviewPass ? { x: 0, y: 0, extent: N } : offscreenCaches.morph.viewport || { x: 0, y: 0, extent: N };
            const S = Math.min(view.extent, 1024);
            const rowAt = pixel => view.y + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));
            const colAt = pixel => view.x + Math.min(view.extent - 1, Math.floor((pixel + 0.5) * view.extent / S));


            const imgData = offscreenCaches.morph.ctx.createImageData(S, S);
            const data32 = new Uint32Array(imgData.data.buffer);
            const isOriginMode = morphColorMode === 'origin';
            const palTable = PALETTE_TABLES_32[currentPalette] || PALETTE_TABLES_32.viridis;
            const blankColor = (255 << 24) | (59 << 16) | (41 << 8) | 30;

            // Precompute Origin Mode colors:
            // Reference PDB: #3498db (RGB 52, 152, 219)
            const colorPDB = (255 << 24) | (219 << 16) | (152 << 8) | 52;
            // AlphaFold: #2eccbf (RGB 46, 204, 191)
            const colorAF = (255 << 24) | (191 << 16) | (204 << 8) | 46;
            // Neither: much darker grey (matching the grey for those cells when not in origin mode: blankColor / #1e293b)
            const colorNeither = blankColor;

            // Both: blend between #3498db and #2eccbf based on how much from each (1-alpha from PDB, alpha from AF)
            const w1 = 1.0 - morphAlpha;
            const w2 = morphAlpha;
            const rBoth = Math.round(w1 * 52 + w2 * 46);
            const gBoth = Math.round(w1 * 152 + w2 * 204);
            const bBoth = Math.round(w1 * 219 + w2 * 191);
            const colorBoth = (255 << 24) | (bBoth << 16) | (gBoth << 8) | rBoth;

            let minVal = 0, maxVal = 1;
            if (!isOriginMode) {
                const bounds = await fullMatrixRange(offscreenCaches.morph, contentKey, N,
                    (i,j) => getMorphCellValue(morphMatrixPositions[i], morphMatrixPositions[j], morphAlpha)?.value ?? null, checkpoint);
                if (!bounds || !valid()) return;
                minVal = bounds.min; maxVal = bounds.max;
            }
            const morphRange = maxVal - minVal;

            for (let pixelI = 0; pixelI < S; pixelI++) {
                if (!await checkpoint()) return;
                const i = rowAt(pixelI);
                const posI = morphMatrixPositions[i];
                const rowOffset = pixelI * S;
                for (let pixelJ = 0; pixelJ < S; pixelJ++) {
                    const j = colAt(pixelJ);
                    const posJ = morphMatrixPositions[j];
                    const cell = getMorphCellValue(posI, posJ, morphAlpha);
                    if (isOriginMode) {
                        data32[rowOffset + pixelJ] = referenceOriginColor(cell);
                    } else {
                        if (!cell) {
                            data32[rowOffset + pixelJ] = blankColor;
                        } else {
                            // Map distance relative to this morph matrix's min and max values
                            const normByte = Math.max(0, Math.min(255, Math.floor(((cell.value - minVal) / morphRange) * 255)));
                            data32[rowOffset + pixelJ] = palTable[normByte];
                        }
                    }
                    data32[rowOffset + pixelJ] = applyMorphOpacity(data32[rowOffset + pixelJ], cell && (!showSpringCutoff || cell.value <= springCutoffVal) ? cell.mmsi : 0);
                }
            }

            if (!valid()) return;
            offscreenCaches.morph.canvas.width = S;
            offscreenCaches.morph.canvas.height = S;
            offscreenCaches.morph.ctx.putImageData(imgData, 0, 0);
            offscreenCaches.morph.renderedViewport = { ...view };
            if (overviewPass) saveMatrixOverview(offscreenCaches.morph, contentKey, N);
            offscreenCaches.morph.dirty = false;
            offscreenCaches.morph.lastAlpha = morphAlpha;
            offscreenCaches.morph.lastColorMode = morphColorMode;
        }

        function toggleOriginColorMode() {
            morphColorMode = (morphColorMode === 'origin') ? 'distance' : 'origin';
            updateOriginButtonUI();
            offscreenCaches.morph.dirty = true;
            drawMorphMatrix();
        }

        function updateOriginButtonUI() {
            const btn = document.getElementById('toggleOriginBtn');
            const legend = document.getElementById('originLegendBar');
            if (!btn) return;
            if (morphColorMode === 'origin') {
                btn.className = 'text-white font-medium px-3 py-1.5 rounded-lg text-xs transition flex items-center gap-1.5 shadow ring-2 ring-sky-400/50';
                btn.style.background = `linear-gradient(to right, ${referenceAssembly ? referenceFiles.map((_,i)=>referenceColor(i)).join(', ') + ', ' : '#3498db, '}#2eccbf)`;
                if (legend) legend.classList.remove('hidden');
            } else {
                btn.className = 'bg-slate-800 hover:bg-slate-700 text-slate-200 px-3 py-1.5 rounded-lg text-xs border border-slate-700 transition flex items-center gap-1.5 shadow';
                btn.style.background = '';
                if (legend) legend.classList.add('hidden');
            }
        }

        window.toggleOriginColorMode = toggleOriginColorMode;
        window.updateOriginButtonUI = updateOriginButtonUI;

        function drawMorphMatrix() {

            if (!morphCtx || !morphMatrixSize) {document.getElementById('morphMatrixLoading')?.classList.add('hidden');return;}
            document.getElementById('morphMatrixLoading')?.classList.toggle('hidden',offscreenCaches.morph.overviewKey===matrixContentKey('morph',''));
            const N = morphMatrixSize;
            updateMatrixResolutionNotice('morphResolutionNotice', updateMatrixViewport(offscreenCaches.morph, N, morphCanvas, morphScale, morphOffX, morphOffY));

            morphCtx.clearRect(0, 0, morphCanvas.width, morphCanvas.height);
            morphCtx.fillStyle = document.body.classList.contains('light-mode') ? '#f8fafc' : '#020617';
            morphCtx.fillRect(0, 0, morphCanvas.width, morphCanvas.height);

            if (offscreenCaches.morph.dirty || offscreenCaches.morph.lastAlpha !== morphAlpha || offscreenCaches.morph.lastColorMode !== morphColorMode) {
                scheduleMatrixRender(offscreenCaches.morph, (checkpoint, valid) => updateOffscreenMorphMatrix(checkpoint, valid), drawMorphMatrix);
            }

            morphCtx.imageSmoothingEnabled = false;
            drawMatrixViewport(morphCtx, offscreenCaches.morph, morphScale, morphOffX, morphOffY);

            // Block boundaries
            if (morphMatrixBlocks.length > 0) {
                const chainKeys = morphMatrixBlocks.map(b => b.c1);
                for (let b = 0; b < morphMatrixBlocks.length; b++) {
                    const block = morphMatrixBlocks[b];
                    const color = getChainColor(block.c1, chainKeys);
                    const segStartPx = morphOffX + block.offset * morphScale;
                    const segStartPy = morphOffY + block.offset * morphScale;
                    const segLen = block.length * morphScale;
                    morphCtx.fillStyle = color;
                    morphCtx.fillRect(segStartPx, morphOffY - 7, segLen, 5);
                    morphCtx.fillRect(morphOffX - 7, segStartPy, 5, segLen);
                }

                morphCtx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
                morphCtx.lineWidth = 1;
                morphCtx.setLineDash([3, 3]);
                for (let k = 1; k < morphMatrixBlocks.length; k++) {
                    const boundaryIdx = morphMatrixBlocks[k].offset;
                    const bx = morphOffX + boundaryIdx * morphScale;
                    const by = morphOffY + boundaryIdx * morphScale;
                    morphCtx.beginPath(); morphCtx.moveTo(bx, morphOffY - 7); morphCtx.lineTo(bx, morphOffY + N * morphScale); morphCtx.stroke();
                    morphCtx.beginPath(); morphCtx.moveTo(morphOffX - 7, by); morphCtx.lineTo(morphOffX + N * morphScale, by); morphCtx.stroke();
                }
                morphCtx.setLineDash([]);
            }

            if (morphHoverCell && morphHoverCell.i >= 0 && morphHoverCell.i < N && morphHoverCell.j >= 0 && morphHoverCell.j < N) {
                morphCtx.strokeStyle = '#ffffff';
                morphCtx.lineWidth = 1.5;
                morphCtx.strokeRect(morphOffX + morphHoverCell.j * morphScale, morphOffY + morphHoverCell.i * morphScale, Math.max(1, morphScale), Math.max(1, morphScale));
            }
            drawLinkedMatrixSelection(morphCtx,morphScale,morphOffX,morphOffY,'morph');
        }

// matrixRendering.js end

// matrixInteraction.js start
        // ==========================================
        // 7. HOVER HANDLERS WITH O(1) MATRIX LOOKUPS
        // ==========================================
        function handleSingleHover(mouseX, mouseY, modelData, scale, offX, offY, tooltipId, canvas, modelNum) {
            const atoms = modelData.currentChain === 'ALL' ? modelData.caAtoms : (modelData.chains[modelData.currentChain] || []);
            const N = atoms.length;
            if (!N) return;

            const j = Math.floor((mouseX - offX) / scale);
            const i = Math.floor((mouseY - offY) / scale);
            const tooltip = document.getElementById(tooltipId);

            if (i >= 0 && i < N && j >= 0 && j < N) {
                if (modelNum === 1) hoverCell1 = { i, j }; else hoverCell2 = { i, j };
                const a1 = atoms[i], a2 = atoms[j];
                const differentSource = a1.fileIndex !== undefined && a2.fileIndex !== undefined && a1.fileIndex !== a2.fileIndex;

                const res1Label = a1.sourcePdbId ? `${a1.sourcePdbId} ${displayChainName(a1.chainId)}` : displayChainName(a1.chainId);
                const res2Label = a2.sourcePdbId ? `${a2.sourcePdbId} ${displayChainName(a2.chainId,'alphaFold')}` : displayChainName(a2.chainId,'alphaFold');

                // Instant O(1) lookup from cached flat Float32Array - zero allocation!
                const matrix = getOrComputeDistanceMatrix(modelData, modelData.currentChain, atoms);
                const dist = matrix[i * N + j];

                let distanceLine = differentSource || dist < 0
                    ? `<div class="font-mono font-bold text-slate-500 mt-1">Distance: N/A (different source files)</div>`
                    : `<div class="font-mono font-bold text-amber-400 mt-1">Distance: ${dist.toFixed(2)} Å</div>`;

                tooltip.innerHTML = `
                    <div class="font-semibold border-b border-slate-800 pb-1 mb-1 ${modelNum === 1 ? 'text-indigo-300' : 'text-teal-300'}">
                        Model ${modelNum} Distance
                    </div>
                    <div class="font-mono text-slate-300">Res 1: ${escapeHtml(res1Label)} ${escapeHtml(a1.resName)}${escapeHtml(a1.resSeq)}</div>
                    <div class="font-mono text-slate-300">Res 2: ${escapeHtml(res2Label)} ${escapeHtml(a2.resName)}${escapeHtml(a2.resSeq)}</div>
                    ${distanceLine}
                `;
                tooltip.style.left = `${Math.min(mouseX + 15, canvas.width - 200)}px`;
                tooltip.style.top = `${Math.min(mouseY + 15, canvas.height - 110)}px`;
                tooltip.classList.remove('hidden');
                drawIndividualMatrices();
            } else {
                if (modelNum === 1 && hoverCell1 !== null) { hoverCell1 = null; tooltip.classList.add('hidden'); drawIndividualMatrices(); }
                else if (modelNum === 2 && hoverCell2 !== null) { hoverCell2 = null; tooltip.classList.add('hidden'); drawIndividualMatrices(); }
            }
        }

        function handleDiffHover(mouseX, mouseY) {
            if (!alignmentResults.length || selectedPairKey === null) return;
            const res = alignmentResults[selectedPairKey];
            if (!res) return;

            const pairs = res.alignedPairs;
            const N = pairs.length;
            const j = Math.floor((mouseX - diffOffX) / diffScale);
            const i = Math.floor((mouseY - diffOffY) / diffScale);
            const tooltip = document.getElementById('diffTooltip');

            if (i >= 0 && i < N && j >= 0 && j < N) {
                diffHoverCell = { i, j };
                const pairI = pairs[i], pairJ = pairs[j];
                const valid1 = pairI.idx1 !== null && pairJ.idx1 !== null;
                const valid2 = pairI.idx2 !== null && pairJ.idx2 !== null;

                document.getElementById('diffTooltipPos').textContent = `Aligned Positions: [${i + 1}, ${j + 1}]`;

                if (valid1 && valid2 && !res.atoms1[pairI.idx1].sequenceOnly && !res.atoms2[pairI.idx2].sequenceOnly && !res.atoms1[pairJ.idx1].sequenceOnly && !res.atoms2[pairJ.idx2].sequenceOnly) {
                    const mat1 = getOrComputeDistanceMatrix(modelData1, res.c1, res.atoms1);
                    const mat2 = getOrComputeDistanceMatrix(modelData2, res.c2, res.atoms2);
                    const d1 = mat1[pairI.idx1 * res.atoms1.length + pairJ.idx1];
                    const d2 = mat2[pairI.idx2 * res.atoms2.length + pairJ.idx2];
                    const delta = Math.abs(d1 - d2);

                    const resI1 = res.atoms1[pairI.idx1], resJ1 = res.atoms1[pairJ.idx1];
                    const resI2 = res.atoms2[pairI.idx2], resJ2 = res.atoms2[pairJ.idx2];

                    document.getElementById('diffTooltipPDB').textContent = `Reference PDB (${res.c1}): ${resI1.resName}${resI1.resSeq} - ${resJ1.resName}${resJ1.resSeq} = ${d1.toFixed(2)} Å`;
                    document.getElementById('diffTooltipAF').textContent = `AlphaFold (${res.c2}): ${resI2.resName}${resI2.resSeq} - ${resJ2.resName}${resJ2.resSeq} = ${d2.toFixed(2)} Å`;
                    document.getElementById('diffTooltipDelta').textContent = `Distance Shift |Δ|: ${delta.toFixed(2)} Å`;
                } else {
                    document.getElementById('diffTooltipPDB').textContent = `Reference PDB: ${valid1 ? 'Valid' : 'Gap Alignment'}`;
                    document.getElementById('diffTooltipAF').textContent = `AlphaFold: ${valid2 ? 'Valid' : 'Gap Alignment'}`;
                    document.getElementById('diffTooltipDelta').textContent = `Distance Shift: N/A (Gap Position)`;
                }

                tooltip.style.left = `${Math.min(mouseX + 15, diffCanvas.width - 240)}px`;
                tooltip.style.top = `${Math.min(mouseY + 15, diffCanvas.height - 130)}px`;
                tooltip.classList.remove('hidden');
                drawDifferenceMatrix();
            } else {
                if (diffHoverCell !== null) { diffHoverCell = null; tooltip.classList.add('hidden'); drawDifferenceMatrix(); }
            }
        }

        function handleMorphHover(mouseX, mouseY) {
            if (!morphMatrixSize) return;
            const N = morphMatrixSize;
            const j = Math.floor((mouseX - morphOffX) / morphScale);
            const i = Math.floor((mouseY - morphOffY) / morphScale);
            const tooltip = document.getElementById('morphTooltip');

            if (i >= 0 && i < N && j >= 0 && j < N) {
                morphHoverCell = { i, j };
                const posI = morphMatrixPositions[i], posJ = morphMatrixPositions[j];
                const cell = getMorphCellValue(posI, posJ, morphAlpha);
                const sameChain = posI.blockIdx === posJ.blockIdx;
                renderMorphTooltipReferences(cell);
                document.getElementById('morphTooltipPDB').classList.toggle('hidden',!!referenceAssembly);
                document.getElementById('morphTooltipMMSI').textContent = `Influence on sim: ${Math.round((cell ? cell.mmsi : 0) * 100)}%`;

                document.getElementById('morphTooltipPos').textContent =
                    `${displayChainName(posI.res.c1)} [${(i - morphMatrixBlocks[posI.blockIdx].offset) + 1}] × ${displayChainName(posJ.res.c1)} [${(j - morphMatrixBlocks[posJ.blockIdx].offset) + 1}]`;

                if (cell) {
                    if (sameChain) {
                        document.getElementById('morphTooltipPDB').textContent = `${referenceAssembly?'D_ref (weighted)':'D1 (Reference PDB)'}: ${cell.d1 !== null ? cell.d1.toFixed(2) + ' Å' : 'N/A (gap)'}`;
                        document.getElementById('morphTooltipAF').textContent = `D_AF (AlphaFold): ${cell.d2 !== null ? cell.d2.toFixed(2) + ' Å' : 'N/A (gap)'}`;
                        document.getElementById('morphTooltipInterpolated').textContent = cell.morphed
                            ? `D_morph${referenceAssembly?'':` (α = ${morphAlpha.toFixed(2)})`}: ${cell.value.toFixed(2)} Å [Intra-chain]`
                            : `D_morph: ${cell.value.toFixed(2)} Å [Intra-chain]`;
                    } else {
                        document.getElementById('morphTooltipPDB').textContent = `${referenceAssembly?'D_ref (weighted)':'D1 (Reference PDB)'}: ${cell.d1!==null?cell.d1.toFixed(2)+' Å':'N/A (gap)'}`;
                        document.getElementById('morphTooltipAF').textContent = `D_AF (AlphaFold): ${cell.d2!==null?cell.d2.toFixed(2)+' Å':'N/A (gap)'}`;
                        document.getElementById('morphTooltipInterpolated').textContent = `D_morph: ${cell.value.toFixed(2)} Å [Inter-chain]`;
                    }
                } else {
                    document.getElementById('morphTooltipPDB').textContent = `Reference PDB: Gap Alignment`;
                    document.getElementById('morphTooltipAF').textContent = `AlphaFold: Gap Alignment`;
                    document.getElementById('morphTooltipInterpolated').textContent = `D_morph: N/A (Gap Position)`;
                }

                const originEl = document.getElementById('morphTooltipOrigin');
                if (originEl) {
                    if (morphColorMode === 'origin') {
                        originEl.classList.remove('hidden');
                        if(referenceAssembly) {
                            const sources=cell?.references?.flatMap((value,i)=>value===null?[]:[referenceFiles[i].pdbId])||[];
                            if(cell?.d2!==null&&cell)sources.push('AlphaFold');
                            originEl.textContent='Origin: '+(sources.length?sources.join(' + '):'Neither (alignment gap)');
                            originEl.style.color=cell?'#e2e8f0':'#94a3b8';
                        } else if (!cell) {
                            originEl.innerHTML = `<span class="text-slate-400 font-semibold"><i class="fa-solid fa-square mr-1" style="color: #1e293b;"></i> Origin: Neither (Dark Grey)</span>`;
                        } else if (cell.d1 !== null && cell.d2 !== null) {
                            const pct1 = Math.round((1 - morphAlpha) * 100);
                            const pct2 = Math.round(morphAlpha * 100);
                            originEl.innerHTML = `<span class="font-semibold text-slate-200"><i class="fa-solid fa-square mr-1" style="color: #3498db;"></i> Origin: Both (<span style="color: #3498db;">${pct1}% PDB</span> + <span style="color: #2eccbf;">${pct2}% AF</span>)</span>`;
                        } else if (cell.d1 !== null) {
                            originEl.innerHTML = `<span class="font-semibold" style="color: #3498db;"><i class="fa-solid fa-square mr-1" style="color: #3498db;"></i> Origin: Reference PDB only</span>`;
                        } else if (cell.d2 !== null) {
                            originEl.innerHTML = `<span class="font-semibold" style="color: #2eccbf;"><i class="fa-solid fa-square mr-1" style="color: #2eccbf;"></i> Origin: AlphaFold only</span>`;
                        }
                    } else {
                        originEl.classList.add('hidden');
                    }
                }

                tooltip.classList.remove('hidden');
                tooltip.style.left = `${Math.max(0,Math.min(mouseX + 15, morphCanvas.width - tooltip.offsetWidth - 8))}px`;
                tooltip.style.top = `${Math.max(0,Math.min(mouseY + 15, morphCanvas.height - tooltip.offsetHeight - 8))}px`;
                drawMorphMatrix();
            } else {
                if (morphHoverCell !== null) { morphHoverCell = null; tooltip.classList.add('hidden'); drawMorphMatrix(); }
            }
        }

// matrixInteraction.js end

// morphMatrixData.js start
        // ==========================================
        // 8. COMBINED MORPH MATRIX INDEX & CELLS
        // ==========================================
        function buildMorphMatrixBlocks() {
            morphMatrixBlocks = [];
            morphMatrixPositions = [];
            physicsPositions = [];
            let offset = 0;

            alignmentResults.forEach((res, bIdx) => {
                const length = res.alignedPairs.length;
                // Keep the matrix's union axis separate from the AF-only simulation.
                const pairsByAF = new Map(res.alignedPairs
                    .filter(pair => pair.idx2 !== null)
                    .map(pair => [pair.idx2, pair]));
                const physicsPairs = res.referenceOnly
                    ? res.atoms1.map((_,i)=>({idx1:i,idx2:i}))
                    : res.atoms2.map((_, idx2) => pairsByAF.get(idx2) || { idx1: null, idx2 });
                morphMatrixBlocks.push({ res, c1: res.c1, offset, length, blockIdx: bIdx, physicsPairs });

                res.alignedPairs.forEach(pair => {
                    const posEntry = { blockIdx: bIdx, res, pair };
                    morphMatrixPositions.push(posEntry);

                });

                physicsPairs.forEach(pair => {
                    physicsPositions.push({ blockIdx: bIdx, res, pair });
                });
                offset += length;
            });

            morphMatrixSize = offset;
            offscreenCaches.morph.dirty = true;
        }

        // Compute Morph matrix simulation influence (MMSI)
        function getMorphMMSI(d1, d2) {
            if (d1 !== null && d2 !== null) return (model1Influence + model2Influence) / 2;
            if (d1 !== null) return model1Influence;
            if (d2 !== null) return model2Influence;
            return 0;
        }
        function model2InterChainDistance(posI, posJ) {
            if(posI.res.referenceOnly||posJ.res.referenceOnly)return null;
            if (posI.pair.idx2 === null || posJ.pair.idx2 === null) return null;
            const a = posI.res.atoms2[posI.pair.idx2], b = posJ.res.atoms2[posJ.pair.idx2];
            if (!a || !b || a.sequenceOnly || b.sequenceOnly || a.fileIndex === undefined || a.fileIndex !== b.fileIndex) return null;
            // One AlphaFold chain can be reused for several reference chains. Those
            // copies do not provide experimental/predicted inter-chain geometry.
            if (posI.res.atoms2 === posJ.res.atoms2 || (a.groupKey && b.groupKey ? a.groupKey === b.groupKey : a.chainId === b.chainId)) return null;
            return dist3d(a, b);
        }

        // Composite cell opacity over the exact alignment-gap colour (#1e293b).
        function applyMorphOpacity(color, mmsi) {
            const r = Math.round(30 + ((color & 255) - 30) * mmsi);
            const g = Math.round(41 + (((color >>> 8) & 255) - 41) * mmsi);
            const b = Math.round(59 + (((color >>> 16) & 255) - 59) * mmsi);
            return (255 << 24) | (b << 16) | (g << 8) | r;
        }

        function getMorphCellValue(posI, posJ, alpha) {
            const sameChain=posI.blockIdx===posJ.blockIdx;
            const pairI=posI.pair,pairJ=posJ.pair;
            let references=referenceCellDistances(posI,posJ);
            let d1=null,d2=null;
            if(references) d1=blendedReferenceDistance(references);
            else if(sameChain && pairI.idx1!==null && pairJ.idx1!==null) {
                const res=posI.res,mat1=getOrComputeDistanceMatrix(modelData1,res.c1,res.atoms1);
                d1=mat1[pairI.idx1*res.atoms1.length+pairJ.idx1];
            } else if(!sameChain && pairI.idx1!==null && pairJ.idx1!==null) d1=dist3d(posI.res.atoms1[pairI.idx1],posJ.res.atoms1[pairJ.idx1]);
            if(sameChain && pairI.idx2!==null && pairJ.idx2!==null) {
                const res=posI.res,mat2=getOrComputeDistanceMatrix(modelData2,res.c2,res.atoms2);
                d2=mat2[pairI.idx2*res.atoms2.length+pairJ.idx2];
            } else if(!sameChain) d2=model2InterChainDistance(posI,posJ);
            if(d1!==null&&(!Number.isFinite(d1)||d1<0))d1=null;
            if(d2!==null&&(!Number.isFinite(d2)||d2<0))d2=null;
            if(d1===null&&d2===null)return null;
            const value=d1===null?d2:d2===null?d1:references?blendAvailableReferenceAndAlphaFold(references,d2):(1-alpha)*d1+alpha*d2;
            const referenceInfluence=references?references.reduce((n,v,i)=>n+(v===null?0:referenceInfluences[i]??1),0)/Math.max(1,references.filter(v=>v!==null).length):model1Influence;
            const mmsi=d1!==null&&d2!==null?(referenceInfluence+model2Influence)/2:d1!==null?referenceInfluence:model2Influence;
            return {value,d1,d2,mmsi,interChain:!sameChain,morphed:d1!==null&&d2!==null,references};
        }

// morphMatrixData.js end

// physicsScene.js start
        // ==========================================
        // 9. HIGH-PERFORMANCE THREE.JS PHYSICS ENGINE
        // ==========================================
        // Key optimizations:
        // 1) InstancedMesh for 1357 C-alpha nodes: renders all nodes in 1 single WebGL draw call!
        // 2) Cutoff-filtered sparse springs: for 6YKM, creates ~20,000 springs instead of 920,000!
        // 3) Pre-allocated dynamic buffer lines for backbone: zero geometry reallocation per frame!
        // 4) Spatial hashing: drops steric check from O(N^2) to O(N)!
        function initThreeJSPhysicsScene() {
            const container = document.getElementById('physics3dCanvas');
            if (!container) return;

            physicsScene = new THREE.Scene();
            physicsScene.background = new THREE.Color(document.body.classList.contains('light-mode') ? 0xffffff : 0x020617);

            const width = container.clientWidth || 1230;
            const height = container.clientHeight || 520;

            physicsCamera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
            resetPhysicsCamera();

            physicsRenderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
            const renderPhysicsScene=physicsRenderer.render.bind(physicsRenderer);
            physicsRenderer.render=(scene,camera)=>{syncPhysicsTransparency(scene);renderPhysicsScene(scene,camera);};
            physicsRenderer.setSize(width, height);
            physicsRenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            container.appendChild(physicsRenderer.domElement);

            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            physicsScene.add(ambientLight);

            const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.8);
            dirLight1.position.set(50, 100, 50);
            physicsScene.add(dirLight1);

            const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.8);
            dirLight2.position.set(-50, -50, -50);
            physicsScene.add(dirLight2);

            backboneLinesGroup = new THREE.Group();
            physicsScene.add(backboneLinesGroup);

            nodeDummy = new THREE.Object3D();

            const el = physicsRenderer.domElement;
            el.style.cursor = 'grab';
            el.style.touchAction = 'none';
            let touchView = null;
            const touchPoint = touch => ({x:touch.clientX,y:touch.clientY});
            const touchGesture = touches => {
                if (touches.length >= 2) {
                    const a=touchPoint(touches[0]),b=touchPoint(touches[1]);
                    return {count:2,x:(a.x+b.x)/2,y:(a.y+b.y)/2,distance:Math.hypot(a.x-b.x,a.y-b.y)};
                }
                if (touches.length === 1) return {count:1,...touchPoint(touches[0])};
                return null;
            };
            let touchDraggingPhysics = false;
            const touchAsMouse = (type,touch) => new MouseEvent(type,{bubbles:true,button:0,buttons:type==='mouseup'?0:1,clientX:touch.clientX,clientY:touch.clientY});
            el.addEventListener('touchstart', e => {
                e.preventDefault();
                if(touchDraggingPhysics&&e.touches.length!==1){window.dispatchEvent(touchAsMouse('mouseup',e.changedTouches[0]));touchDraggingPhysics=false;}
                if(mobilePhysicsDragMode&&e.touches.length===1&&physicsNodes.length){
                    touchDraggingPhysics=true;touchView=null;el.dispatchEvent(touchAsMouse('mousedown',e.touches[0]));return;
                }
                touchView=touchGesture(e.touches);
            }, {passive:false});
            el.addEventListener('touchmove', e => {
                e.preventDefault();
                if(touchDraggingPhysics){if(e.touches.length===1)window.dispatchEvent(touchAsMouse('mousemove',e.touches[0]));return;}
                const next=touchGesture(e.touches);
                if (!next || !touchView || next.count!==touchView.count) { touchView=next; return; }
                const dx=next.x-touchView.x,dy=next.y-touchView.y;
                if (next.count===1) rotatePhysicsCamera(dx,dy);
                else {
                    physicsCamera.updateMatrixWorld();
                    const right=new THREE.Vector3(),up=new THREE.Vector3();
                    physicsCamera.matrixWorld.extractBasis(right,up,new THREE.Vector3());
                    const distance=physicsCamera.position.distanceTo(camTarget);
                    const pan=right.multiplyScalar(-dx*distance*.0016).add(up.multiplyScalar(dy*distance*.0016));
                    camTarget.add(pan);physicsCamera.position.add(pan);
                    const ratio=touchView.distance>0?next.distance/touchView.distance:1;
                    const offset=physicsCamera.position.clone().sub(camTarget);
                    offset.setLength(Math.max(10,Math.min(5000,offset.length()/Math.max(.1,ratio))));
                    physicsCamera.position.copy(camTarget).add(offset);
                    physicsCamera.far=Math.max(physicsCamera.far,offset.length()*2);
                    physicsCamera.updateProjectionMatrix();
                    physicsCamera.lookAt(camTarget);
                }
                touchView=next;
            }, {passive:false});
            const finishTouch=e=>{
                e.preventDefault();
                if(touchDraggingPhysics){window.dispatchEvent(touchAsMouse('mouseup',e.changedTouches[0]));touchDraggingPhysics=false;}
                touchView=touchGesture(e.touches);
            };
            el.addEventListener('touchend',finishTouch,{passive:false});
            el.addEventListener('touchcancel',finishTouch,{passive:false});

            // Prevent browser context menu on right click everywhere in physics box
            el.addEventListener('contextmenu', (e) => { e.preventDefault(); });
            container.addEventListener('contextmenu', (e) => { e.preventDefault(); });
            const pBox = document.getElementById('physicsContainer');
            if (pBox) pBox.addEventListener('contextmenu', (e) => { e.preventDefault(); });

            el.addEventListener('mousedown', (e) => {
                is3dMouseDown = true;
                mouse3dButton = e.button;
                prevMouse3dX = e.clientX;
                prevMouse3dY = e.clientY;

                if(!animationPlaying&&!animationPreparing&&e.button===0&&(e.shiftKey||mobilePhysicsDragMode==='residue')&&physicsNodes.length){
                    const picked=pickPhysicsObject(e);
                    if(picked?.kind==='node'&&picked.node.res.entityType!=='other'){
                        e.preventDefault();
                        const index=physicsNodes.indexOf(picked.node),visible=visualPointForNode(picked.node);
                        const normal=new THREE.Vector3();physicsCamera.getWorldDirection(normal).negate();
                        dragPlane=new THREE.Plane().setFromNormalAndCoplanarPoint(normal,visible);
                        draggedResidue={index,target:new THREE.Vector3(picked.node.x,picked.node.y,picked.node.z)};
                        el.style.cursor='move';return;
                    }
                }
                if(!animationPlaying&&!animationPreparing&&e.button===0&&e.altKey&&physicsNodes.length){
                    const picked=pickPhysicsObject(e);
                    if(picked?.kind==='node'){
                        updateRotationalSymmetry(true);
                        const group=rotationalSymmetryGroups.find(item=>item.blockIds.has(picked.node.blockIdx));
                        if(group){e.preventDefault();altDraggedSymmetryKey=group.key;el.style.cursor='ew-resize';return;}
                    }
                }

                // Ctrl + Left Click: Click and drag on chains to move them
                if (!animationPlaying&&!animationPreparing&&(e.ctrlKey || e.metaKey || mobilePhysicsDragMode==='chain') && e.button === 0 && physicsNodes.length > 0) {
                    const rect = el.getBoundingClientRect();
                    const mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
                    const mouseY = -((e.clientY - rect.top) / rect.height) * 2 + 1;
                    const raycaster = new THREE.Raycaster();
                    raycaster.setFromCamera(new THREE.Vector2(mouseX, mouseY), physicsCamera);

                    let closestNodeIdx = -1;
                    let minRayDist = Infinity;
                    const ray = raycaster.ray;
                    const tempV = new THREE.Vector3();

                    for (let i = 0; i < physicsNodes.length; i++) {
                        const node = physicsNodes[i];
                        if (chainVisibility[node.res.c1] === false) continue;
                        tempV.copy(visualPointForNode(node));
                        const d = ray.distanceToPoint(tempV);
                        if (d < 5.0 && d < minRayDist) {
                            minRayDist = d;
                            closestNodeIdx = i;
                        }
                    }

                    if (closestNodeIdx !== -1) {
                        isDraggingChain = true;
                        draggedChainId = physicsNodes[closestNodeIdx].res.c1;
                        draggedBlockIdx = physicsNodes[closestNodeIdx].blockIdx;

                        const planeNormal = new THREE.Vector3();
                        physicsCamera.getWorldDirection(planeNormal).negate();
                        const planePoint = visualPointForNode(physicsNodes[closestNodeIdx]);
                        dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, planePoint);

                        const intersectPoint = new THREE.Vector3();
                        if (ray.intersectPlane(dragPlane, intersectPoint)) {
                            prevDragWorldPos.copy(intersectPoint);
                        } else {
                            prevDragWorldPos.copy(planePoint);
                        }

                        el.style.cursor = 'move';
                        setDragChainBadge(true, draggedChainId);
                        return;
                    }
                }

                isDraggingChain = false;
                el.style.cursor = e.button === 2 ? 'move' : 'grabbing';
            });
            let selectionPointer=null;
            function pickPhysicsObject(event) {
                if(!physicsCamera)return null;
                const rect=el.getBoundingClientRect();
                const mouse=new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);
                const raycaster=new THREE.Raycaster();raycaster.setFromCamera(mouse,physicsCamera);
                let picked=null,best=Infinity;
                if(physicsRepresentation==='ball-stick'&&atomRepresentation?.balls?.visible){
                    const hit=raycaster.intersectObject(atomRepresentation.balls,false).find(item=>item.instanceId!==undefined&&isNodeVisibleInPhysics(physicsNodes[atomRepresentation.entries[item.instanceId]?.nodeIndex]));
                    if(hit){picked={kind:'node',node:physicsNodes[atomRepresentation.entries[hit.instanceId].nodeIndex]};best=hit.distance;}
                }
                if(membraneLipids&&lipidsVisible){
                    const hit=pickMembraneLipid(raycaster);
                    if(hit?.particle&&hit.distance<best){picked={kind:'lipid',particle:hit.particle};best=hit.distance;}
                }
                if(picked)return picked;
                for (const node of physicsNodes) {
                    if (!isNodeVisibleInPhysics(node)) continue;
                    const point=visualPointForNode(node);
                    const distance=raycaster.ray.distanceToPoint(point);
                    const depth=physicsCamera.position.distanceTo(point);
                    if(distance<Math.max(1.8,depth*.012)&&depth<best){picked={kind:'node',node};best=depth;}
                }
                return picked;
            }
            let lastSelectionHover=0;
            el.addEventListener('pointermove',event=>{
                if(event.pointerType==='touch'||event.buttons||isDraggingChain)return;
                const now=performance.now();if(now-lastSelectionHover<45)return;lastSelectionHover=now;
                el.style.cursor=pickPhysicsObject(event)?'pointer':'grab';
            });
            el.addEventListener('pointerdown',event=>{ if(event.button===0&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!mobilePhysicsDragMode) selectionPointer={x:event.clientX,y:event.clientY}; });
            el.addEventListener('pointerup',event=>{
                if (!selectionPointer||Math.hypot(event.clientX-selectionPointer.x,event.clientY-selectionPointer.y)>5||!physicsCamera) { selectionPointer=null; return; }
                selectionPointer=null;
                const selected=pickPhysicsObject(event);
                if(selected?.kind==='lipid')selectLipid(selected.particle);
                else if (selected?.kind==='node') {
                    const node=selected.node;
                    const atom=node.idx1===null?node.res.atoms2[node.idx2]:node.res.atoms1[node.idx1];
                    selectLinkedEntity(node.res.c1,atom?.resSeq,selectionMode,atom,event.shiftKey);
                } else clearLinkedSelection();
            });

            window.addEventListener('mouseup', () => {
                if (is3dMouseDown) {
                    if(isDraggingChain||draggedResidue||altDraggedSymmetryKey)scheduleAnimationCapture();
                    is3dMouseDown = false;
                    if (isDraggingChain) {
                        isDraggingChain = false;
                        draggedChainId = null;
                        draggedBlockIdx = -1;
                        setDragChainBadge(false);
                    }
                    draggedResidue=null;
                    altDraggedSymmetryKey=null;
                    if (el) el.style.cursor = 'grab';
                }
            });

            window.addEventListener('mousemove', (e) => {
                if (is3dMouseDown) {
                    if(draggedResidue){
                        const rect=el.getBoundingClientRect();
                        const mouse=new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);
                        const raycaster=new THREE.Raycaster();raycaster.setFromCamera(mouse,physicsCamera);
                        const visibleTarget=new THREE.Vector3();
                        if(raycaster.ray.intersectPlane(dragPlane,visibleTarget)){
                            const node=physicsNodes[draggedResidue.index];
                            const group=visualRotationForNode(node);
                            draggedResidue.target.copy(group?rotateVisualPoint(visibleTarget,group,-group.angle):visibleTarget);
                            pinDraggedResidue();
                        }
                        return;
                    }
                    if(altDraggedSymmetryKey){
                        const group=rotationalSymmetryGroups.find(item=>item.key===altDraggedSymmetryKey);
                        if(group){group.angle+=(e.clientX-prevMouse3dX)*.012;updateResetRotationButton();updateSymmetryRotationControls();}
                        prevMouse3dX=e.clientX;prevMouse3dY=e.clientY;
                        return;
                    }
                    if (isDraggingChain) {
                        const rect = el.getBoundingClientRect();
                        const mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
                        const mouseY = -((e.clientY - rect.top) / rect.height) * 2 + 1;
                        const raycaster = new THREE.Raycaster();
                        raycaster.setFromCamera(new THREE.Vector2(mouseX, mouseY), physicsCamera);

                        const currentIntersect = new THREE.Vector3();
                        if (raycaster.ray.intersectPlane(dragPlane, currentIntersect)) {
                            const group=visualRotationForNode(physicsNodes.find(node=>node.blockIdx===draggedBlockIdx));
                            const previous=group?rotateVisualPoint(prevDragWorldPos,group,-group.angle):prevDragWorldPos;
                            const current=group?rotateVisualPoint(currentIntersect,group,-group.angle):currentIntersect;
                            const dx=current.x-previous.x,dy=current.y-previous.y,dz=current.z-previous.z;
                            prevDragWorldPos.copy(currentIntersect);

                            for (let i = 0; i < physicsNodes.length; i++) {
                                const node = physicsNodes[i];
                                if (node.res.c1 === draggedChainId || node.blockIdx === draggedBlockIdx) {
                                    node.x += dx;
                                    node.y += dy;
                                    node.z += dz;
                                }
                            }
                        }
                        return;
                    }

                    const dx = e.clientX - prevMouse3dX;
                    const dy = e.clientY - prevMouse3dY;
                    prevMouse3dX = e.clientX;
                    prevMouse3dY = e.clientY;

                    if (mouse3dButton === 2) {
                        // Pan camera: move camTarget in camera's view plane (right-click drag)
                        physicsCamera.updateMatrixWorld();
                        const right = new THREE.Vector3();
                        const up = new THREE.Vector3();
                        physicsCamera.matrixWorld.extractBasis(right, up, new THREE.Vector3());
                        const curDist = physicsCamera.position.distanceTo(camTarget);
                        const panSpeed = curDist * 0.0016;
                        const panOffset = right.clone().multiplyScalar(-dx * panSpeed).add(up.clone().multiplyScalar(dy * panSpeed));
                        camTarget.add(panOffset);
                        physicsCamera.position.add(panOffset);
                        physicsCamera.lookAt(camTarget);
                    } else {
                        // Full unrestricted orbit in 3D: rotate around camera's local right vector for pitch, and around up vector for yaw (NO limits up/down!)
                        rotatePhysicsCamera(dx, dy);
                    }
                }
            });
            el.addEventListener('wheel', (e) => {
                e.preventDefault();
                if (!physicsCamera) return;
                physicsCamera.updateMatrixWorld();
                const offset = physicsCamera.position.clone().sub(camTarget);
                const curDist = offset.length();
                const scrollPixels=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?el.clientHeight:1);
                const zoomFactor=Math.exp(Math.max(-1,Math.min(1,scrollPixels*.00075)));
                const newDist = Math.max(10, Math.min(5000, curDist * zoomFactor));
                offset.setLength(newDist);
                physicsCamera.position.copy(camTarget).add(offset);
                physicsCamera.far=Math.max(physicsCamera.far,newDist*2);
                physicsCamera.updateProjectionMatrix();
                physicsCamera.lookAt(camTarget);
            });

            window.addEventListener('resize', () => {
                if (!physicsRenderer || !container) return;
                const w = container.clientWidth, h = container.clientHeight;
                physicsCamera.aspect = w / h;
                physicsCamera.updateProjectionMatrix();
                physicsRenderer.setSize(w, h);
            });
        }

        // Full unrestricted 3D orbit around camTarget with no pitch limits
        function rotatePhysicsCameraByAngles(yawAngle, pitchAngle) {
            if (!physicsCamera) return;
            physicsCamera.updateMatrixWorld();
            const offset = physicsCamera.position.clone().sub(camTarget);

            // Extract camera's local axes
            const right = new THREE.Vector3();
            const up = new THREE.Vector3();
            const forward = new THREE.Vector3();
            physicsCamera.matrixWorld.extractBasis(right, up, forward);

            // Up/Down pitch: rotate offset around camera's local right vector.
            offset.applyAxisAngle(right, pitchAngle);
            physicsCamera.up.applyAxisAngle(right, pitchAngle);

            // Left/Right yaw: rotate offset around camera's up vector.
            offset.applyAxisAngle(physicsCamera.up, yawAngle);

            physicsCamera.position.copy(camTarget).add(offset);
            physicsCamera.lookAt(camTarget);
        }

        function rotatePhysicsCamera(dx, dy) {
            rotatePhysicsCameraByAngles(-dx * 0.008, -dy * 0.008);
        }

        function resetPhysicsCamera() {
            camTarget.set(0, 0, 0);
            if (!physicsCamera) return;
            physicsCamera.up.set(0, 1, 0);
            camRadius = 180;
            physicsCamera.position.set(camRadius * 0.5, camRadius * 0.6, camRadius * 0.7);
            physicsCamera.lookAt(camTarget);
        }

        function autoFitPhysicsCamera() {
            if (!physicsCamera || !physicsNodes.length) return;
            const points = physicsNodes.map(visualPointForNode);
            const bounds = new THREE.Box3().setFromPoints(points);
            const target = bounds.getCenter(new THREE.Vector3());
            const size = bounds.getSize(new THREE.Vector3());
            const radius = Math.max(size.length() * 0.5, 1);
            let viewDirection = physicsCamera.position.clone().sub(camTarget).normalize();
            let up = physicsCamera.up.clone().normalize();

            if (inferredMembrane) {
                updateMembraneSideNames();
                const normal = new THREE.Vector3(...inferredMembrane.normal).normalize();
                const horizontal = new THREE.Vector3(...inferredMembrane.u).normalize();
                const positiveIsCytoplasmic = /cytoplas|cytosol|intracellular|inside/i.test(membraneSideNames.positive);
                const negativeIsCytoplasmic = /cytoplas|cytosol|intracellular|inside/i.test(membraneSideNames.negative);
                const cytoplasmicNormal = positiveIsCytoplasmic&&!negativeIsCytoplasmic ? normal
                    : negativeIsCytoplasmic&&!positiveIsCytoplasmic ? normal.clone().negate() : normal;
                viewDirection = horizontal;
                up = cytoplasmicNormal.negate();
            }

            camTarget.copy(target);
            physicsCamera.position.copy(target).addScaledVector(viewDirection, Math.max(10, radius));
            physicsCamera.up.copy(up);
            physicsCamera.lookAt(target);
            const distance = radius / Math.tan(THREE.MathUtils.degToRad(physicsCamera.fov * 0.5)) * 1.15;
            camRadius = distance;
            physicsCamera.position.copy(target).addScaledVector(viewDirection, Math.max(10, distance));
            physicsCamera.far = Math.max(1000, distance + radius * 2);
            physicsCamera.updateProjectionMatrix();
            physicsCamera.lookAt(target);
        }

        function updatePhysicsCameraPosition() {
            resetPhysicsCamera();
        }
