            const ctx = canvas.getContext('2d'), w = springHistogramWidth || 190, h = 78, pixelRatio = 4;
            canvas.width = w * pixelRatio; canvas.height = h * pixelRatio; ctx.setTransform(pixelRatio,0,0,pixelRatio,0,0); ctx.clearRect(0,0,w,h);
            const left=24,right=5,top=5,bottom=18,plotW=w-left-right,plotH=h-top-bottom,bins=48,counts=new Array(bins).fill(0);
            for(const sp of physicsSprings){const active=getActiveSpring(sp);if(!active)continue;const a=physicsNodes[sp.i],b=physicsNodes[sp.j];if(!a||!b)continue;const strain=Math.max(-1,Math.min(1,(Math.hypot(b.x-a.x,b.y-a.y,b.z-a.z)-active.targetRestLen)/Math.max(active.targetRestLen,.001)/.5));counts[Math.min(bins-1,Math.max(0,Math.floor((strain+1)*.5*bins)))]++;}
