            ctx.fillStyle='#94a3b8';ctx.font='9px sans-serif';ctx.fillText('-50%',left-10,h-4);ctx.fillText('0',left+plotW/2-3,h-4);ctx.fillText('+50%',left+plotW-22,h-4);
