            const angle=Math.hypot(rx,ry,rz);
            if(!angle)return [x,y,z];
            const scale=Math.sin(angle/2)/angle,qx=rx*scale,qy=ry*scale,qz=rz*scale,qw=Math.cos(angle/2);
            const tx=2*(qy*z-qz*y),ty=2*(qz*x-qx*z),tz=2*(qx*y-qy*x);
