                        const [a,b,c]=nodes,u=[a.x-b.x,a.y-b.y,a.z-b.z],v=[c.x-b.x,c.y-b.y,c.z-b.z];
                        const u2=u.reduce((sum,value)=>sum+value*value,0),v2=v.reduce((sum,value)=>sum+value*value,0);
