            F:'#c084fc',W:'#c084fc',Y:'#c084fc',
            S:'#38bdf8',T:'#38bdf8',N:'#38bdf8',Q:'#38bdf8',C:'#38bdf8',
            K:'#fb7185',R:'#fb7185',H:'#fb7185',D:'#4ade80',E:'#4ade80'
