                if(block.nodes.length<12)continue;
                const atoms=block.res.atoms2;
                const sequence=atoms.map(atom=>atom.singleChar||'X').join('');
                const key=/[^X]/.test(sequence)?sequence:atoms[0]?.sourcePdbId||sequence;
