            const N=physicsNodes.length,features=Array.from({length:N},()=>({hydrogen:false,salt:false,disulfide:false,ligand:false}));
            const contacts=new Set(),grid=new Map(),cell=12,key=(x,y,z)=>`${x}:${y}:${z}`;
