                link.href=url;link.download=`${(animationTitle||'animation').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'')||'animation'}-table.csv`;
                document.body.append(link);link.click();link.remove();
                setTimeout(()=>URL.revokeObjectURL(url),60000);
